/* ==========================================================================
   PREMIUM FURNITURE SHOP - CORE DESIGN SYSTEM
   ========================================================================== */

:root {
  /* ------------------------------------------------------------------------
     DESIGN TOKENS (PALETTE & BASE METRICS)
     ------------------------------------------------------------------------ */
  /* Light Theme Reference Colors */
  --fur-ref-beige-50: hsl(36, 30%, 98%);
  --fur-ref-beige-100: hsl(36, 24%, 94%);
  --fur-ref-beige-200: hsl(36, 18%, 88%);
  --fur-ref-beige-300: hsl(36, 12%, 80%);
  --fur-ref-green-900: hsl(0, 0%, 25%);
  --fur-ref-green-800: hsl(88, 38%, 26%);
  --fur-ref-green-700: hsl(88, 38%, 32%);
  --fur-ref-green-100: hsl(88, 20%, 90%);
  --fur-ref-charcoal: hsl(0, 0%, 11%);
  --fur-ref-grey-500: hsl(0, 0%, 45%);
  --fur-ref-grey-200: hsl(0, 0%, 85%);
  --fur-ref-white: hsl(0, 0%, 100%);
  --fur-ref-overlay-light: hsla(0, 0%, 0%, 0.12);

  /* Forest Dark Theme Reference Colors */
  --fur-ref-forest-950: hsl(126, 34%, 5%);
  --fur-ref-forest-900: hsl(126, 34%, 8%);
  --fur-ref-forest-800: hsl(125, 22%, 12%);
  --fur-ref-forest-700: hsl(125, 18%, 18%);
  --fur-ref-forest-600: hsl(125, 15%, 25%);
  --fur-ref-olive-500: hsl(88, 36%, 31%);
  --fur-ref-lime-400: hsl(88, 44%, 50%);
  --fur-ref-lime-500: hsl(88, 44%, 44%);
  --fur-ref-beige-dark: hsl(36, 20%, 90%);
  --fur-ref-beige-dark-muted: hsl(38, 10%, 74%);
  --fur-ref-overlay-dark: hsla(0, 0%, 0%, 0.45);

  /* Fonts */
  --fur-font-serif: 'Playfair Display', Georgia, serif;
  --fur-font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --fur-font-script: 'Alex Brush', cursive;

  /* Border Radii */
  --fur-radius-sm: 8px;
  --fur-radius-md: 16px;
  --fur-radius-lg: 24px;
  --fur-radius-xl: 32px;
  --fur-radius-full: 9999px;

  /* Transitions */
  --fur-transition-fast: 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  --fur-transition-normal: 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  --fur-transition-slow: 0.6s cubic-bezier(0.16, 1, 0.3, 1);

  /* ------------------------------------------------------------------------
     DYNAMIC PROPERTY MAPPINGS (DEFAULT: BEIGE LIGHT)
     ------------------------------------------------------------------------ */
  --fur-bg: var(--fur-ref-beige-100);
  --fur-bg-secondary: var(--fur-ref-beige-50);
  --fur-surface: var(--fur-ref-white);
  --fur-surface-secondary: var(--fur-ref-beige-50);
  --fur-text: var(--fur-ref-charcoal);
  --fur-text-muted: var(--fur-ref-grey-500);
  --fur-primary: var(--fur-ref-green-900);
  --fur-primary-hover: var(--fur-ref-green-700);
  --fur-accent: var(--fur-ref-green-900);
  --fur-border: var(--fur-ref-beige-200);
  --fur-border-light: var(--fur-ref-beige-300);

  --fur-sidebar-bg: var(--fur-ref-white);
  --fur-sidebar-text: var(--fur-ref-charcoal);
  --fur-sidebar-active: var(--fur-ref-green-100);
  --fur-sidebar-card-bg: var(--fur-ref-beige-100);

  --fur-hero-overlay: var(--fur-ref-overlay-light);
  --fur-shadow: hsla(0, 0%, 0%, 0.04);
  --fur-shadow-lg: hsla(0, 0%, 0%, 0.12);

  --fur-card-bg: var(--fur-ref-white);
  --fur-button-text: var(--fur-ref-white);
  --fur-badge-bg: var(--fur-ref-green-900);
  --fur-badge-text: var(--fur-ref-white);
  --fur-card-hover-bg: var(--fur-ref-beige-50);

  --fur-ticker-bg: var(--fur-ref-beige-100);
  --fur-ticker-text: var(--fur-ref-green-900);

  --fur-scrollbar-thumb: var(--fur-ref-beige-300);
  --fur-scrollbar-track: var(--fur-ref-beige-100);

  /* Fluid Typography & Margins */
  --fur-fs-h1: clamp(2.4rem, 4vw, 4.4rem);
  --fur-fs-h2: clamp(1.8rem, 2.5vw, 2.6rem);
  --fur-fs-h3: clamp(1.25rem, 1.8vw, 1.75rem);
  --fur-fs-body: clamp(0.9rem, 1.1vw, 1.05rem);
  --fur-fs-small: clamp(0.75rem, 0.9vw, 0.85rem);

  --fur-margin-block-lg: clamp(2rem, 3.5vw, 4.5rem);
  --fur-margin-block-md: clamp(1rem, 2vw, 2.5rem);
}

/* ==========================================================================
   CSS RESET & WORDPRESS-READY BASE STYLES
   ========================================================================== */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-family: var(--fur-font-sans);
  background-color: var(--fur-bg);
  color: var(--fur-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-size: var(--fur-fs-body);
  line-height: 1.6;
  background-color: var(--fur-bg);
  color: var(--fur-text);
  overflow: hidden;
  transition: background-color var(--fur-transition-normal), color var(--fur-transition-normal);
}

/* WP-Native Standard resets & Hooks */
.sticky {
  position: sticky;
  inset-block-start: 0;
  z-index: 90;
}

.alignwide {
  max-width: 1200px;
  margin-inline: auto;
}

.alignfull {
  width: 100%;
  max-width: 100%;
}

.bypostauthor {
  border: 1px solid var(--fur-primary);
}

a {
  color: inherit;
  text-decoration: none;
  transition: color var(--fur-transition-fast);
}

button {
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  color: inherit;
  outline: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
}

ul,
ol {
  list-style: none;
}

/* Custom Scrollbar for App elements */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: var(--fur-scrollbar-track);
}

::-webkit-scrollbar-thumb {
  background: var(--fur-scrollbar-thumb);
  border-radius: var(--fur-radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--fur-primary);
}

/* Inline SVG structure */
.fur-icon {
  display: inline-block;
  vertical-align: middle;
  flex-shrink: 0;
}

/* ==========================================================================
   APP CONTAINER & LAYOUT SPLIT (3-COLUMN SYSTEM)
   ========================================================================== */
.fur-app-layout {
  display: flex;
  flex-direction: row;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
  position: relative;
}

/* ==========================================================================
   1. LEFT SIDEBAR (fur-sidebar)
   ========================================================================== */
.fur-sidebar {
  width: 280px;
  height: 100%;
  background-color: var(--fur-sidebar-bg);
  border-inline-end: 1px solid var(--fur-border);
  display: flex;
  flex-direction: column;
  padding-block: var(--fur-margin-block-md);
  padding-inline: var(--fur-margin-block-md);
  flex-shrink: 0;
  z-index: 10;
  transition: background-color var(--fur-transition-normal), border-color var(--fur-transition-normal);
}

.fur-sidebar__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-block-end: var(--fur-margin-block-lg);
}

.fur-sidebar__logo {
  font-family: var(--fur-font-sans);
  font-weight: 800;
  font-size: 2.2rem;
  letter-spacing: -2px;
  color: var(--fur-sidebar-text);
  line-height: 1;
}

.fur-sidebar__logo-dot {
  color: hsl(88, 38%, 31%);
}

.fur-sidebar__toggle {
  display: none;
}

.fur-sidebar__nav {
  flex-grow: 1;
  overflow-y: auto;
  margin-block-end: var(--fur-margin-block-md);
}

.fur-sidebar__nav-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.fur-sidebar__nav-link {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-inline: 16px;
  padding-block: 12px;
  border-radius: var(--fur-radius-md);
  color: var(--fur-text-muted);
  font-weight: 500;
  font-size: var(--fur-fs-small);
  transition: all var(--fur-transition-normal);
}

.fur-sidebar__nav-link .fur-icon {
  transition: transform var(--fur-transition-normal);
}

.fur-sidebar__nav-link:hover {
  color: var(--fur-text);
  background-color: var(--fur-bg-secondary);
}

.fur-sidebar__nav-link:hover .fur-icon {
  transform: translateX(3px);
}

[dir="rtl"] .fur-sidebar__nav-link:hover .fur-icon {
  transform: translateX(-3px);
}

.fur-sidebar__nav-item--active .fur-sidebar__nav-link {
  color: var(--fur-primary);
  background-color: var(--fur-sidebar-active);
  font-weight: 600;
}

.fur-sidebar__widgets {
  margin-block-end: var(--fur-margin-block-md);
}

.fur-sidebar__card {
  background-color: var(--fur-sidebar-card-bg);
  border-radius: var(--fur-radius-lg);
  padding-inline: 20px;
  padding-block: 20px;
  position: relative;
  overflow: hidden;
  transition: background-color var(--fur-transition-normal);
}

.fur-sidebar__card-content {
  position: relative;
  z-index: 2;
}

.fur-sidebar__card-title {
  font-family: var(--fur-font-sans);
  font-weight: 700;
  font-size: var(--fur-fs-body);
  margin-block-end: 8px;
}

.fur-sidebar__card-text {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  margin-block-end: 16px;
}

.fur-sidebar__card-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  font-size: var(--fur-fs-small);
  color: var(--fur-primary);
}

.fur-sidebar__card-link:hover .fur-icon {
  transform: translateX(4px);
}

[dir="rtl"] .fur-sidebar__card-link:hover .fur-icon {
  transform: translateX(-4px);
}

.fur-sidebar__card-leaf {
  position: absolute;
  inset-inline-end: -8px;
  inset-block-end: -8px;
  color: var(--fur-primary);
  opacity: 0.15;
  pointer-events: none;
  transform: rotate(-15deg);
}

.fur-sidebar__footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-block-start: 1px solid var(--fur-border);
  padding-block-start: 16px;
}

.fur-sidebar__action-btn {
  width: 44px;
  height: 44px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: var(--fur-radius-full);
  color: var(--fur-text-muted);
  transition: all var(--fur-transition-normal);
  position: relative;
}

.fur-sidebar__action-btn:hover {
  color: var(--fur-text);
  background-color: var(--fur-bg-secondary);
}

.fur-sidebar__cart-count {
  position: absolute;
  inset-block-start: 4px;
  inset-inline-end: 4px;
  background-color: var(--fur-badge-bg);
  color: var(--fur-badge-text);
  font-size: 0.65rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  border-radius: var(--fur-radius-full);
  display: flex;
  justify-content: center;
  align-items: center;
  padding-inline: 4px;
}

/* ==========================================================================
   2. CENTRAL HERO PANE (fur-hero)
   ========================================================================== */
.fur-hero {
  flex: 0 0 38vw;
  height: 100%;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding-block: var(--fur-margin-block-lg);
  padding-inline: var(--fur-margin-block-lg);
  color: var(--fur-ref-white);
  border-inline-end: 1px solid var(--fur-border);
}

.fur-hero__background-slider {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.fur-hero__bg-slide {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0;
  transform: scale(1.08);
  transition: opacity var(--fur-transition-slow), transform var(--fur-transition-slow);
}

.fur-hero__bg-slide--active {
  opacity: 1;
  transform: scale(1);
}

.fur-hero__overlay {
  position: absolute;
  inset: 0;
  background: var(--fur-hero-overlay);
  z-index: 2;
  transition: background var(--fur-transition-normal);
}

.fur-hero__content {
  position: relative;
  z-index: 3;
  margin-block-start: auto;
  margin-block-end: var(--fur-margin-block-lg);
}

.fur-hero__subtitle {
  text-transform: uppercase;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 2px;
  display: block;
  margin-block-end: 16px;
  color: hsla(0, 0%, 100%, 0.85);
  animation: fadeInUp 0.8s ease;
}

.fur-hero__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h1);
  font-weight: 400;
  line-height: 1.15;
  margin-block-end: 20px;
  letter-spacing: -1px;
}

.fur-hero__title-italic {
  font-family: var(--fur-font-script);
  font-size: 1.25em;
  font-style: italic;
  font-weight: 400;
  color: hsl(88, 44%, 50%);
  display: inline-block;
  transform: translateY(4px);
  margin-inline-start: 4px;
}

.fur-hero__description {
  font-size: var(--fur-fs-body);
  color: hsla(0, 0%, 100%, 0.85);
  max-width: 90%;
  margin-block-end: 32px;
}

.fur-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-block-end: var(--fur-margin-block-lg);
}

.fur-hero__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding-inline: 28px;
  padding-block: 16px;
  border-radius: var(--fur-radius-full);
  font-weight: 600;
  font-size: var(--fur-fs-small);
  transition: all var(--fur-transition-normal);
}

.fur-hero__btn--primary {
  background-color: var(--fur-ref-green-900);
  color: var(--fur-ref-white);
  border: 1px solid var(--fur-ref-green-900);
}

.fur-hero__btn--primary:hover {
  background-color: var(--fur-ref-green-700);
  border-color: var(--fur-ref-green-700);
  transform: translateY(-2px);
}

.fur-hero__btn--outline {
  background-color: transparent;
  color: var(--fur-ref-white);
  border: 1px solid hsla(0, 0%, 100%, 0.4);
  backdrop-filter: blur(10px);
}

.fur-hero__btn--outline:hover {
  background-color: hsla(0, 0%, 100%, 0.1);
  border-color: hsla(0, 0%, 100%, 1);
  transform: translateY(-2px);
}

.fur-hero__social-proof {
  display: flex;
  align-items: center;
  gap: 16px;
}

.fur-hero__avatars {
  display: flex;
}

.fur-hero__avatar {
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  border: 2px solid var(--fur-ref-green-900);
  background-color: var(--fur-ref-beige-200);
  display: flex;
  justify-content: center;
  align-items: center;
  color: transparent;
  margin-inline-start: -10px;
  background-size: cover;
  background-position: center;
}

.fur-hero__avatars .fur-hero__avatar:first-child {
  margin-inline-start: 0;
  background-image: url('assets/img/fur_room_living.html');
}

.fur-hero__avatars .fur-hero__avatar:nth-child(2) {
  background-image: url('assets/img/fur_room_bedroom.html');
}

.fur-hero__avatars .fur-hero__avatar:nth-child(3) {
  background-image: url('assets/img/fur_room_dining.html');
}

.fur-hero__proof-text {
  font-size: var(--fur-fs-small);
  color: hsla(0, 0%, 100%, 0.9);
}

.fur-hero__trust-strip {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-inline: 24px;
  padding-block: 24px;
  background: hsla(0, 0%, 0%, 0.25);
  backdrop-filter: blur(20px);
  border: 1px solid hsla(0, 0%, 100%, 0.1);
  border-radius: var(--fur-radius-lg);
}

.fur-hero__trust-item {
  display: flex;
  align-items: center;
  gap: 16px;
}

.fur-hero__trust-item .fur-icon {
  color: hsl(88, 44%, 50%);
  width: 24px;
  height: 24px;
}

.fur-hero__trust-item div {
  display: flex;
  flex-direction: column;
}

.fur-hero__trust-item strong {
  font-size: var(--fur-fs-small);
  font-weight: 600;
  color: var(--fur-ref-white);
}

.fur-hero__trust-item span {
  font-size: 0.75rem;
  color: hsla(0, 0%, 100%, 0.7);
}

/* ==========================================================================
   3. RIGHT CONTENT FEED (fur-main)
   ========================================================================== */
.fur-main {
  flex: 1;
  height: 100%;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  padding-block: 0;
  padding-inline: 0;
  background-color: var(--fur-bg);
  transition: background-color var(--fur-transition-normal);
}

/* STICKY HEADER WITH THEME SWITCHER */
.fur-header {
  position: sticky;
  inset-block-start: 0;
  z-index: 20;
  background-color: hsla(36, 24%, 94%, 0.8);
  backdrop-filter: blur(20px);
  border-block-end: 1px solid var(--fur-border);
  padding-inline: var(--fur-margin-block-md);
  padding-block: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: all var(--fur-transition-normal);
}

body[data-theme="dark"] .fur-header {
  background-color: hsla(126, 34%, 8%, 0.8);
}

.fur-header__ticker {
  display: flex;
  align-items: center;
  gap: 12px;
  overflow: hidden;
  max-width: 60%;
}

.fur-header__tag {
  background-color: var(--fur-ticker-bg);
  color: var(--fur-ticker-text);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding-inline: 8px;
  padding-block: 4px;
  border-radius: var(--fur-radius-sm);
  white-space: nowrap;
}

.fur-header__ticker-wrap {
  overflow: hidden;
  white-space: nowrap;
}

.fur-header__ticker-text {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  font-weight: 500;
}

.fur-header__actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* THEME SWITCHER TOGGLE */
.fur-theme-switcher {
  display: flex;
  background-color: var(--fur-bg-secondary);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-full);
  padding-inline: 4px;
  padding-block: 4px;
}

.fur-theme-switcher__btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-inline: 12px;
  padding-block: 6px;
  border-radius: var(--fur-radius-full);
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--fur-text-muted);
  transition: all var(--fur-transition-normal);
}

.fur-theme-switcher__btn--active {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
}

.fur-header__user-nav {
  display: none;
  /* Only visible on smaller screens when sidebar footer is hidden */
  gap: 8px;
}

.fur-header__nav-btn {
  width: 40px;
  height: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: var(--fur-radius-full);
  color: var(--fur-text-muted);
  position: relative;
  transition: all var(--fur-transition-normal);
}

.fur-header__nav-btn:hover {
  color: var(--fur-text);
  background-color: var(--fur-bg-secondary);
}

.fur-header__cart-count {
  position: absolute;
  inset-block-start: 2px;
  inset-inline-end: 2px;
  background-color: var(--fur-badge-bg);
  color: var(--fur-badge-text);
  font-size: 0.6rem;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: var(--fur-radius-full);
  display: flex;
  justify-content: center;
  align-items: center;
}

/* CATEGORY SCROLLER STRIP */
.fur-categories {
  padding-inline: var(--fur-margin-block-md);
  padding-block: var(--fur-margin-block-md);
  border-block-end: 1px solid var(--fur-border);
}

.fur-categories__scroller {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  /* Hide default scrollbar */
}

.fur-categories__scroller::-webkit-scrollbar {
  display: none;
}

.fur-categories__btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding-inline: 20px;
  padding-block: 12px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  font-weight: 600;
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  white-space: nowrap;
  scroll-snap-align: start;
  transition: all var(--fur-transition-normal);
}

.fur-categories__btn:hover {
  border-color: var(--fur-primary);
  color: var(--fur-text);
}

.fur-categories__btn--active {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  border-color: var(--fur-primary);
}

/* MAIN PROMO SLIDER */
.fur-promo {
  padding-inline: var(--fur-margin-block-md);
  padding-block: var(--fur-margin-block-md);
  position: relative;
}

.fur-promo__slider {
  position: relative;
  height: 380px;
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  box-shadow: 0 4px 20px var(--fur-shadow);
}

.fur-promo__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding-inline: 40px;
  padding-block: 40px;
  transition: opacity var(--fur-transition-slow);
}

.fur-promo__slide--active {
  opacity: 1;
  z-index: 2;
}

.fur-promo__slide-image-wrap {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.fur-promo__slide-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 6s ease;
}

.fur-promo__slide--active .fur-promo__slide-img {
  transform: scale(1.05);
}

.fur-promo__slide::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, hsla(0, 0%, 0%, 0.85) 0%, hsla(0, 0%, 0%, 0.2) 60%, transparent 100%);
  z-index: 2;
}

.fur-promo__slide-content {
  position: relative;
  z-index: 3;
  max-width: 500px;
  color: var(--fur-ref-white);
}

.fur-promo__tag {
  text-transform: uppercase;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--fur-accent);
  background-color: var(--fur-ref-white);
  padding-inline: 10px;
  padding-block: 4px;
  border-radius: var(--fur-radius-sm);
  display: inline-block;
  margin-block-end: 12px;
}

.fur-promo__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h2);
  font-weight: 400;
  margin-block-end: 12px;
  line-height: 1.2;
}

.fur-promo__desc {
  font-size: var(--fur-fs-small);
  color: hsla(0, 0%, 100%, 0.85);
  margin-block-end: 24px;
}

.fur-promo__btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-weight: 700;
  font-size: var(--fur-fs-small);
  color: var(--fur-ref-white);
}

.fur-promo__btn-arrow {
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-accent);
  color: var(--fur-button-text);
  display: flex;
  justify-content: center;
  align-items: center;
  transition: transform var(--fur-transition-normal);
}

.fur-promo__btn:hover .fur-promo__btn-arrow {
  transform: scale(1.1);
}

.fur-promo__controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-block-start: 16px;
  padding-inline: 8px;
}

.fur-promo__dots {
  display: flex;
  gap: 8px;
}

.fur-promo__dot {
  width: 8px;
  height: 8px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-border-light);
  transition: all var(--fur-transition-normal);
}

.fur-promo__dot--active {
  width: 24px;
  background-color: var(--fur-primary);
}

.fur-promo__arrows {
  display: flex;
  gap: 8px;
}

.fur-promo__arrow-btn {
  width: 36px;
  height: 36px;
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-full);
  display: flex;
  justify-content: center;
  align-items: center;
  color: var(--fur-text);
  background-color: var(--fur-surface);
  transition: all var(--fur-transition-normal);
}

.fur-promo__arrow-btn:hover {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  border-color: var(--fur-primary);
}

/* SECTION HEADERS */
.fur-section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-block-end: var(--fur-margin-block-md);
  padding-inline: var(--fur-margin-block-md);
  margin-block-start: var(--fur-margin-block-lg);
}

.fur-section-header__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h2);
  font-weight: 400;
  line-height: 1.2;
}

.fur-section-header__link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  font-size: var(--fur-fs-small);
  color: var(--fur-primary);
}

.fur-section-header__link:hover .fur-icon {
  transform: translateX(4px);
}

[dir="rtl"] .fur-section-header__link:hover .fur-icon {
  transform: translateX(-4px);
}

/* ROOMS GRID */
.fur-rooms-grid {
  padding-inline: 0;
}

.fur-rooms-grid__layout {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--fur-margin-block-md);
  padding-inline: var(--fur-margin-block-md);
}

.fur-room-card {
  background-color: var(--fur-card-bg);
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  border: 1px solid var(--fur-border);
  transition: all var(--fur-transition-normal);
  cursor: pointer;
}

.fur-room-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 30px var(--fur-shadow-lg);
  border-color: var(--fur-primary);
}

.fur-room-card__img-wrap {
  height: 220px;
  overflow: hidden;
  position: relative;
}

.fur-room-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--fur-transition-slow);
}

.fur-room-card:hover .fur-room-card__img {
  transform: scale(1.05);
}

.fur-room-card__footer {
  padding-inline: 20px;
  padding-block: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.fur-room-card__title {
  font-family: var(--fur-font-sans);
  font-size: var(--fur-fs-body);
  font-weight: 700;
  margin-block-end: 4px;
}

.fur-room-card__count {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
}

.fur-room-card__btn {
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-bg-secondary);
  color: var(--fur-text);
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all var(--fur-transition-normal);
}

.fur-room-card:hover .fur-room-card__btn {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
}

/* STYLES GRID */
.fur-styles {
  padding-inline: 0;
}

.fur-styles__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  padding-inline: var(--fur-margin-block-md);
}

.fur-style-card {
  background-color: var(--fur-card-bg);
  border-radius: var(--fur-radius-md);
  border: 1px solid var(--fur-border);
  overflow: hidden;
  transition: all var(--fur-transition-normal);
  cursor: pointer;
}

.fur-style-card:hover {
  transform: translateY(-4px);
  border-color: var(--fur-primary);
  box-shadow: 0 8px 24px var(--fur-shadow-lg);
}

.fur-style-card__img-wrap {
  height: 140px;
  overflow: hidden;
}

.fur-style-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--fur-transition-slow);
}

.fur-style-card:hover .fur-style-card__img {
  transform: scale(1.06);
}

.fur-style-card__footer {
  padding-inline: 16px;
  padding-block: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.fur-style-card__title {
  font-size: 0.85rem;
  font-weight: 700;
  margin-block-end: 2px;
}

.fur-style-card__count {
  font-size: 0.75rem;
  color: var(--fur-text-muted);
}

.fur-style-card__arrow {
  width: 28px;
  height: 28px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-bg-secondary);
  display: flex;
  justify-content: center;
  align-items: center;
  color: var(--fur-text-muted);
  transition: all var(--fur-transition-normal);
}

.fur-style-card:hover .fur-style-card__arrow {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
}

/* SALE STRIP */
.fur-sale-strip {
  margin-inline: var(--fur-margin-block-md);
  margin-block-start: var(--fur-margin-block-lg);
  background-color: var(--fur-bg-secondary);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-lg);
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  overflow: hidden;
  align-items: center;
  transition: all var(--fur-transition-normal);
}

.fur-sale-strip__content {
  padding-inline: 40px;
  padding-block: 40px;
}

.fur-sale-strip__tag {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--fur-primary);
  display: block;
  margin-block-end: 12px;
}

.fur-sale-strip__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h2);
  font-weight: 400;
  margin-block-end: 12px;
  line-height: 1.2;
}

.fur-sale-strip__desc {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  margin-block-end: 24px;
}

.fur-sale-strip__btn {
  display: inline-block;
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  font-weight: 600;
  font-size: var(--fur-fs-small);
  padding-inline: 28px;
  padding-block: 14px;
  border-radius: var(--fur-radius-full);
  transition: all var(--fur-transition-normal);
}

.fur-sale-strip__btn:hover {
  background-color: var(--fur-primary-hover);
  transform: translateY(-2px);
}

.fur-sale-strip__graphic {
  position: relative;
  height: 100%;
  min-height: 220px;
}

.fur-sale-strip__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.fur-sale-strip__badge {
  position: absolute;
  inset-block-start: 20px;
  inset-inline-start: 20px;
  background-color: hsl(88, 44%, 50%);
  color: var(--fur-ref-charcoal);
  width: 72px;
  height: 72px;
  border-radius: var(--fur-radius-full);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  box-shadow: 0 4px 15px hsla(0, 0%, 0%, 0.15);
  animation: pulse 2s infinite;
}

.fur-sale-strip__badge strong {
  font-size: 1.15rem;
  font-weight: 800;
  line-height: 1;
}

.fur-sale-strip__badge span {
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

/* PRODUCT CARD GRID */
.fur-products {
  padding-inline: 0;
}

.fur-products__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  padding-inline: var(--fur-margin-block-md);
}

.fur-product-card {
  background-color: var(--fur-card-bg);
  border-radius: var(--fur-radius-md);
  border: 1px solid var(--fur-border);
  overflow: hidden;
  position: relative;
  transition: all var(--fur-transition-normal);
  display: flex;
  flex-direction: column;
}

.fur-product-card:hover {
  transform: translateY(-4px);
  border-color: var(--fur-primary);
  box-shadow: 0 8px 24px var(--fur-shadow-lg);
}

.fur-product-card__img-wrap {
  aspect-ratio: 1;
  overflow: hidden;
  position: relative;
  background-color: var(--fur-bg-secondary);
}

.fur-product-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--fur-transition-slow);
}

.fur-product-card:hover .fur-product-card__img {
  transform: scale(1.05);
}

.fur-product-card__wishlist {
  position: absolute;
  inset-block-start: 12px;
  inset-inline-end: 12px;
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-surface);
  color: var(--fur-text-muted);
  box-shadow: 0 2px 8px var(--fur-shadow);
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all var(--fur-transition-normal);
  z-index: 3;
}

.fur-product-card__wishlist:hover {
  color: hsl(0, 80%, 60%);
  transform: scale(1.1);
}

.fur-product-card__wishlist--active {
  color: hsl(0, 80%, 60%);
  background-color: var(--fur-surface);
}

.fur-product-card__wishlist--active svg {
  fill: currentColor;
}

.fur-product-card__info {
  padding-inline: 16px;
  padding-block: 16px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.fur-product-card__title {
  font-size: 0.9rem;
  font-weight: 600;
  margin-block-end: 6px;
  color: var(--fur-text);
  cursor: pointer;
}

.fur-product-card__title:hover {
  color: var(--fur-primary);
}

.fur-product-card__price {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--fur-primary);
  margin-block-end: 16px;
}

.fur-product-card__add-btn {
  margin-block-start: auto;
  width: 100%;
  background-color: var(--fur-bg-secondary);
  color: var(--fur-text);
  border: 1px solid var(--fur-border);
  font-size: 0.8rem;
  font-weight: 600;
  padding-block: 10px;
  border-radius: var(--fur-radius-full);
  transition: all var(--fur-transition-normal);
}

.fur-product-card__add-btn:hover {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  border-color: var(--fur-primary);
}

/* JOURNAL BANNER (BOTTOM) */
.fur-journal {
  padding-inline: var(--fur-margin-block-md);
  margin-block-start: var(--fur-margin-block-lg);
  margin-block-end: var(--fur-margin-block-lg);
}

.fur-journal__card {
  background-color: var(--fur-card-bg);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  align-items: center;
  transition: all var(--fur-transition-normal);
}

.fur-journal__img-wrap {
  height: 100%;
  min-height: 250px;
}

.fur-journal__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.fur-journal__content {
  padding-inline: 40px;
  padding-block: 40px;
}

.fur-journal__icon-box {
  width: 48px;
  height: 48px;
  border-radius: var(--fur-radius-md);
  background-color: var(--fur-bg-secondary);
  color: var(--fur-primary);
  display: flex;
  justify-content: center;
  align-items: center;
  margin-block-end: 20px;
}

.fur-journal__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h2);
  font-weight: 400;
  margin-block-end: 12px;
}

.fur-journal__desc {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  margin-block-end: 24px;
}

.fur-journal__btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: var(--fur-fs-small);
  color: var(--fur-primary);
}

.fur-journal__btn:hover .fur-icon {
  transform: translateX(4px);
}

[dir="rtl"] .fur-journal__btn:hover .fur-icon {
  transform: translateX(-4px);
}

/* FOOTER SECTION */
.fur-footer {
  background-color: var(--fur-bg-secondary);
  border-block-start: 1px solid var(--fur-border);
  padding-inline: var(--fur-margin-block-md);
  padding-block: var(--fur-margin-block-lg) var(--fur-margin-block-md);
  margin-block-start: auto;
  transition: all var(--fur-transition-normal);
}

.fur-footer__main {
  display: grid;
  grid-template-columns: 1.2fr 2.8fr;
  gap: 48px;
  margin-block-end: var(--fur-margin-block-lg);
}

.fur-footer__logo {
  font-family: var(--fur-font-sans);
  font-weight: 800;
  font-size: 2rem;
  letter-spacing: -1.5px;
  margin-block-end: 16px;
}

.fur-footer__tagline {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  max-width: 220px;
}

.fur-footer__links-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.fur-footer__col h4 {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-block-end: 20px;
}

.fur-footer__col ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.fur-footer__col a {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
}

.fur-footer__col a:hover {
  color: var(--fur-primary);
}

.fur-footer__bottom {
  border-block-start: 1px solid var(--fur-border);
  padding-block-start: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.fur-footer__copy {
  font-size: 0.75rem;
  color: var(--fur-text-muted);
}

.fur-footer__legal {
  display: flex;
  gap: 24px;
}

.fur-footer__legal a {
  font-size: 0.75rem;
  color: var(--fur-text-muted);
}

.fur-footer__legal a:hover {
  color: var(--fur-primary);
}

/* ==========================================================================
   SYSTEM COMPONENT: CART DRAWER (fur-cart-drawer)
   ========================================================================== */
.fur-cart-overlay {
  position: fixed;
  inset: 0;
  background-color: hsla(0, 0%, 0%, 0.4);
  backdrop-filter: blur(4px);
  z-index: 100;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--fur-transition-normal), visibility var(--fur-transition-normal);
}

.fur-cart-overlay[aria-hidden="false"] {
  opacity: 1;
  visibility: visible;
}

.fur-cart-drawer {
  position: absolute;
  inset-block: 0;
  inset-inline-end: 0;
  width: 100%;
  max-width: 440px;
  background-color: var(--fur-surface);
  box-shadow: -10px 0 40px var(--fur-dark-shadow);
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform var(--fur-transition-normal);
}

[dir="rtl"] .fur-cart-drawer {
  transform: translateX(-100%);
}

.fur-cart-overlay[aria-hidden="false"] .fur-cart-drawer {
  transform: translateX(0);
}

.fur-cart-drawer__header {
  padding-inline: 24px;
  padding-block: 24px;
  border-block-end: 1px solid var(--fur-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.fur-cart-drawer__header h3 {
  font-family: var(--fur-font-serif);
  font-size: 1.4rem;
  font-weight: 400;
}

.fur-cart-drawer__close {
  width: 40px;
  height: 40px;
  border-radius: var(--fur-radius-full);
  display: flex;
  justify-content: center;
  align-items: center;
  color: var(--fur-text-muted);
  transition: all var(--fur-transition-normal);
}

.fur-cart-drawer__close:hover {
  background-color: var(--fur-bg-secondary);
  color: var(--fur-text);
}

.fur-cart-drawer__items {
  flex-grow: 1;
  overflow-y: auto;
  padding-inline: 24px;
  padding-block: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.fur-cart-item {
  display: flex;
  gap: 16px;
  align-items: center;
  border-block-end: 1px solid var(--fur-border);
  padding-block-end: 16px;
}

.fur-cart-item__img-wrap {
  width: 80px;
  height: 80px;
  border-radius: var(--fur-radius-md);
  overflow: hidden;
  background-color: var(--fur-bg-secondary);
  flex-shrink: 0;
}

.fur-cart-item__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.fur-cart-item__details {
  flex-grow: 1;
}

.fur-cart-item__title {
  font-size: var(--fur-fs-small);
  font-weight: 600;
  margin-block-end: 4px;
}

.fur-cart-item__price {
  font-size: var(--fur-fs-small);
  font-weight: 700;
  color: var(--fur-primary);
  margin-block-end: 8px;
}

.fur-cart-item__quantity-controls {
  display: flex;
  align-items: center;
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-full);
  width: fit-content;
  padding-inline: 4px;
}

.fur-cart-item__qty-btn {
  width: 24px;
  height: 24px;
  font-size: 0.85rem;
  font-weight: 700;
  display: flex;
  justify-content: center;
  align-items: center;
}

.fur-cart-item__qty-val {
  font-size: 0.8rem;
  font-weight: 600;
  padding-inline: 12px;
}

.fur-cart-item__remove {
  color: var(--fur-text-muted);
  font-size: 0.75rem;
  font-weight: 600;
  text-decoration: underline;
  margin-inline-start: auto;
}

.fur-cart-item__remove:hover {
  color: var(--fur-text);
}

.fur-cart-drawer__footer {
  padding-inline: 24px;
  padding-block: 24px;
  border-block-start: 1px solid var(--fur-border);
  background-color: var(--fur-bg-secondary);
}

.fur-cart-drawer__summary {
  display: flex;
  justify-content: space-between;
  font-weight: 700;
  font-size: var(--fur-fs-body);
  margin-block-end: 20px;
}

.fur-cart-drawer__checkout-btn {
  width: 100%;
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  font-weight: 600;
  padding-block: 16px;
  border-radius: var(--fur-radius-full);
  margin-block-end: 12px;
  transition: all var(--fur-transition-normal);
}

.fur-cart-drawer__checkout-btn:hover {
  background-color: var(--fur-primary-hover);
  transform: translateY(-2px);
}

.fur-cart-drawer__clear-btn {
  width: 100%;
  color: var(--fur-text-muted);
  font-size: var(--fur-fs-small);
  font-weight: 600;
  text-decoration: underline;
  text-align: center;
  transition: color var(--fur-transition-fast);
}

.fur-cart-drawer__clear-btn:hover {
  color: var(--fur-text);
}

/* ==========================================================================
   SYSTEM COMPONENT: PRODUCT DETAILS MODAL (fur-product-modal)
   ========================================================================== */
.fur-modal-overlay {
  position: fixed;
  inset: 0;
  background-color: hsla(0, 0%, 0%, 0.5);
  backdrop-filter: blur(6px);
  z-index: 110;
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--fur-transition-normal), visibility var(--fur-transition-normal);
}

.fur-modal-overlay[aria-hidden="false"] {
  opacity: 1;
  visibility: visible;
}

.fur-modal {
  width: 90%;
  max-width: 800px;
  background-color: var(--fur-surface);
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  box-shadow: 0 20px 50px var(--fur-dark-shadow);
  position: relative;
  transform: scale(0.95);
  transition: transform var(--fur-transition-normal);
}

.fur-modal-overlay[aria-hidden="false"] .fur-modal {
  transform: scale(1);
}

.fur-modal__close {
  position: absolute;
  inset-block-start: 20px;
  inset-inline-end: 20px;
  width: 40px;
  height: 40px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-bg-secondary);
  color: var(--fur-text);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 10;
  transition: all var(--fur-transition-normal);
}

.fur-modal__close:hover {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
}

.fur-modal__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.fur-modal-detail-img-wrap {
  height: 100%;
  min-height: 400px;
  background-color: var(--fur-bg-secondary);
}

.fur-modal-detail-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.fur-modal-detail-info {
  padding-inline: 40px;
  padding-block: 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.fur-modal-detail-category {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--fur-primary);
  margin-block-end: 8px;
}

.fur-modal-detail-title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h2);
  font-weight: 400;
  margin-block-end: 12px;
  line-height: 1.2;
}

.fur-modal-detail-price {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--fur-primary);
  margin-block-end: 20px;
}

.fur-modal-detail-desc {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  margin-block-end: 28px;
  line-height: 1.6;
}

.fur-modal-detail-actions {
  display: flex;
  gap: 16px;
}

.fur-modal-detail-add-btn {
  flex-grow: 1;
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  font-weight: 600;
  font-size: var(--fur-fs-small);
  padding-block: 16px;
  border-radius: var(--fur-radius-full);
  transition: all var(--fur-transition-normal);
}

.fur-modal-detail-add-btn:hover {
  background-color: var(--fur-primary-hover);
  transform: translateY(-2px);
}

.fur-modal-detail-wishlist {
  width: 52px;
  height: 52px;
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-full);
  display: flex;
  justify-content: center;
  align-items: center;
  color: var(--fur-text-muted);
  transition: all var(--fur-transition-normal);
}

.fur-modal-detail-wishlist:hover {
  border-color: var(--fur-primary);
  color: hsl(0, 80%, 60%);
}

.fur-modal-detail-wishlist--active {
  color: hsl(0, 80%, 60%);
}

.fur-modal-detail-wishlist--active svg {
  fill: currentColor;
}


/* ==========================================================================
   KEYFRAME ANIMATIONS
   ========================================================================== */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse {
  0% {
    transform: scale(1);
    box-shadow: 0 4px 15px hsla(88, 44%, 50%, 0.3);
  }

  50% {
    transform: scale(1.05);
    box-shadow: 0 4px 25px hsla(88, 44%, 50%, 0.6);
  }

  100% {
    transform: scale(1);
    box-shadow: 0 4px 15px hsla(88, 44%, 50%, 0.3);
  }
}


/* ==========================================================================
   RESPONSIVE DESIGN OVERRIDES (FLUID CONTAINMENT)
   ========================================================================== */
@media (max-width: 1280px) {
  .fur-sidebar {
    width: 240px;
  }

  .fur-hero {
    flex: 0 0 35vw;
  }

  .fur-rooms-grid__layout {
    grid-template-columns: 1fr;
  }

  .fur-styles__grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .fur-products__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 1024px) {
  .fur-app-layout {
    flex-direction: column;
    height: auto;
    overflow-y: visible;
    overflow-x: hidden;
  }

  /* Sidebar becomes a sticky top bar */
  .fur-sidebar {
    width: 100%;
    height: auto;
    position: sticky;
    inset-block-start: 0;
    border-inline-end: none;
    border-block-end: 1px solid var(--fur-border);
    padding-block: 12px;
    padding-inline: 20px;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    background-color: var(--fur-sidebar-bg);
  }

  .fur-sidebar__header {
    margin-block-end: 0;
    width: auto;
  }

  .fur-sidebar__toggle {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 44px;
    height: 44px;
    border-radius: var(--fur-radius-full);
    border: 1px solid var(--fur-border);
    color: var(--fur-text);
  }

  /* Overlay Navigation Menu on Mobile when opened */
  .fur-sidebar__nav {
    display: none;
    position: fixed;
    inset-block-start: 70px;
    inset-inline: 0;
    background-color: var(--fur-sidebar-bg);
    border-block-end: 1px solid var(--fur-border);
    padding-inline: 20px;
    padding-block: 20px;
    max-height: calc(100vh - 70px);
    overflow-y: auto;
    box-shadow: 0 10px 30px var(--fur-shadow-lg);
  }

  .fur-sidebar__nav--open {
    display: block;
    animation: fadeInUp 0.4s ease;
  }

  .fur-sidebar__widgets {
    display: none;
  }

  .fur-sidebar__footer {
    display: none;
    /* Hidden, functional buttons moved to Header */
  }

  /* Hero pane stacks under the top bar */
  .fur-hero {
    width: 100%;
    height: auto;
    min-height: 80vh;
    flex: none;
    padding-block: var(--fur-margin-block-lg);
    padding-inline: var(--fur-margin-block-lg);
    border-inline-end: none;
    border-block-end: 1px solid var(--fur-border);
  }

  .fur-hero__content {
    margin-block-start: var(--fur-margin-block-lg);
  }

  /* Main Pane flows naturally */
  .fur-main {
    width: 100%;
    height: auto;
    overflow-y: visible;
    flex: none;
  }

  .fur-header__user-nav {
    display: flex;
  }

  .fur-footer__main {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}

@media (max-width: 640px) {
  .fur-hero__actions {
    flex-direction: column;
  }

  .fur-hero__btn {
    width: 100%;
  }

  .fur-sale-strip {
    grid-template-columns: 1fr;
  }

  .fur-sale-strip__graphic {
    min-height: 180px;
  }

  .fur-journal__card {
    grid-template-columns: 1fr;
  }

  .fur-journal__img-wrap {
    min-height: 180px;
  }

  .fur-footer__links-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .fur-modal__content {
    grid-template-columns: 1fr;
  }

  .fur-modal-detail-img-wrap {
    min-height: 250px;
  }

  .fur-modal-detail-info {
    padding-inline: 20px;
    padding-block: 24px;
  }

  .fur-header__ticker {
    display: none;
  }
}

/* ==========================================================================
   HERO REFINEMENTS & READABILITY OVERRIDES (APPENDED)
   ========================================================================== */
:root {
  --fur-glass-dark: hsla(125, 22%, 12%, 0.75);
  --fur-avatar-border: var(--fur-surface);
}

body[data-theme="dark"] {
  --fur-avatar-border: var(--fur-surface);
}

/* Base Hero Overrides */
.fur-hero {
  color: var(--fur-text);
  background-color: var(--fur-bg-secondary);
}

.fur-hero__overlay {
  display: none;
  /* No dark overlay needed in light theme */
}

body[data-theme="dark"] .fur-hero__overlay {
  display: block;
  background: var(--fur-hero-overlay);
}

/* Slides Positioning */
.fur-hero__bg-slide[data-theme="light"] {
  background-size: 60%;
  background-position: bottom right;
  background-repeat: no-repeat;
  background-color: var(--fur-bg-secondary);
}

.fur-hero__bg-slide[data-theme="dark"] {
  background-size: cover;
  background-position: center;
}

/* Text Overrides */
.fur-hero__subtitle {
  color: var(--fur-text-muted);
}

.fur-hero__title {
  color: var(--fur-text);
}

.fur-hero__description {
  color: var(--fur-text-muted);
}

.fur-hero__proof-text {
  color: var(--fur-text);
}

body[data-theme="dark"] .fur-hero__subtitle,
body[data-theme="dark"] .fur-hero__title,
body[data-theme="dark"] .fur-hero__description,
body[data-theme="dark"] .fur-hero__proof-text {
  color: var(--fur-ref-white);
}

/* Hide secondary outline button */
.fur-hero__btn--outline {
  display: none;
}

/* Social Proof Avatars Styling */
.fur-hero__avatars {
  display: flex;
  margin-inline-end: 8px;
}

.fur-hero__avatar {
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  border: 2px solid var(--fur-avatar-border);
  object-fit: cover;
  margin-inline-start: -12px;
}

.fur-hero__avatars .fur-hero__avatar:first-child {
  margin-inline-start: 0;
}

/* Trust Strip Pill Container (Light Mode - Horizontal) */
.fur-hero__trust-strip {
  width: 100%;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-lg);
  padding-block: 20px;
  padding-inline: 24px;
  gap: 16px;
  margin-block-start: auto;
  backdrop-filter: none;
  box-shadow: 0 8px 30px var(--fur-shadow);
}

.fur-hero__trust-item {
  flex: 1 1 0%;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 12px;
  border-inline-end: 1px solid var(--fur-border);
}

.fur-hero__trust-item:last-child {
  border-inline-end: none;
}

.fur-hero__trust-item .fur-icon {
  color: var(--fur-text);
  width: 28px;
  height: 28px;
}

.fur-hero__trust-item strong {
  color: var(--fur-text);
  font-size: 0.85rem;
  line-height: 1.2;
}

.fur-hero__trust-item span {
  color: var(--fur-text-muted);
  font-size: 0.72rem;
  line-height: 1.3;
}

/* Trust Strip Overrides (Dark Mode - Vertical Glassmorphism) */
body[data-theme="dark"] .fur-hero__trust-strip {
  position: absolute;
  inset-block-end: 40px;
  inset-inline-start: 40px;
  width: calc(100% - 80px);
  max-width: 380px;
  flex-direction: column;
  align-items: flex-start;
  background-color: var(--fur-glass-dark);
  backdrop-filter: blur(20px);
  border: 1px solid hsla(0, 0%, 100%, 0.1);
  padding-block: 24px;
  padding-inline: 24px;
  gap: 16px;
  box-shadow: 0 10px 40px var(--fur-shadow-lg);
}

body[data-theme="dark"] .fur-hero__trust-item {
  border-inline-end: none;
  width: 100%;
}

body[data-theme="dark"] .fur-hero__trust-item .fur-icon {
  color: var(--fur-primary);
  width: 24px;
  height: 24px;
}

body[data-theme="dark"] .fur-hero__trust-item strong {
  color: var(--fur-ref-white);
  font-size: var(--fur-fs-small);
}

body[data-theme="dark"] .fur-hero__trust-item span {
  color: hsla(0, 0%, 100%, 0.7);
  font-size: 0.75rem;
}

/* Hide 4th trust item in dark mode for screen mockup parity */
body[data-theme="dark"] .fur-hero__trust-item:nth-child(4) {
  display: none;
}

/* Responsive Overrides */
@media (max-width: 1024px) {
  .fur-hero__bg-slide[data-theme="light"] {
    background-size: 80%;
    background-position: center bottom;
  }

  .fur-hero__trust-strip {
    flex-direction: column;
    align-items: flex-start;
    padding-block: 20px;
    padding-inline: 20px;
  }

  .fur-hero__trust-item {
    border-inline-end: none;
    width: 100%;
  }

  body[data-theme="dark"] .fur-hero__trust-strip {
    position: relative;
    inset-block-end: auto;
    inset-inline-start: auto;
    width: 100%;
    max-width: none;
  }
}

/* ==========================================================================
   DESKTOP HAMBURGER MENU & 50/50 SPLIT SCREEN LAYOUT OVERRIDES (APPENDED)
   ========================================================================== */
@media (min-width: 1025px) {

  /* Narrow Sidebar (80px width) */
  .fur-sidebar {
    width: 80px;
    padding-inline: 12px;
    align-items: center;
  }

  .fur-sidebar__header {
    flex-direction: column;
    gap: 32px;
    margin-block-end: 0;
    width: auto;
  }

  .fur-sidebar__toggle {
    display: flex !important;
    /* Visible on desktop to toggle hamburger menu drawer */
    margin-inline: auto;
  }

  /* Sliding Drawer Navigation */
  .fur-sidebar__nav {
    position: fixed;
    inset-block: 0;
    inset-inline-start: 0;
    width: 280px;
    background-color: var(--fur-sidebar-bg);
    border-inline-end: 1px solid var(--fur-border);
    z-index: 90;
    padding-block: 40px;
    padding-inline: 24px;
    box-shadow: 10px 0 30px var(--fur-shadow);
    transform: translateX(-100%);
    transition: transform var(--fur-transition-normal);
    display: flex;
    flex-direction: column;
  }

  [dir="rtl"] .fur-sidebar__nav {
    transform: translateX(100%);
  }

  .fur-sidebar__nav--open {
    display: flex !important;
    transform: translateX(80px) !important;
  }

  [dir="rtl"] .fur-sidebar__nav--open {
    transform: translateX(-80px) !important;
  }

  .fur-sidebar__widgets {
    display: none !important;
    /* Hide widgets inside narrow bar */
  }

  .fur-sidebar__footer {
    flex-direction: column;
    gap: 20px;
    border-block-start: none;
    padding-block-start: 0;
    width: 100%;
    align-items: center;
  }

  /* 50/50 Split Screen Layout */
  .fur-hero {
    flex: 0 0 calc(50vw - 40px);
    width: calc(50vw - 40px);
  }

  .fur-main {
    flex: 0 0 calc(50vw - 40px);
    width: calc(50vw - 40px);
  }
}

/* Background Image Cover Override for hero-bg.jpg */
.fur-hero__bg-slide[data-theme="light"] {
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}

/* ==========================================================================
   SCROLL-ACTIVATED SPLIT SCREEN TO STANDARD FULL SCREEN TRANSITION (APPENDED)
   ========================================================================== */
@media (min-width: 1025px) {

  /* Transition timings for structural panels */
  .fur-sidebar {
    transition: width 0.8s cubic-bezier(0.16, 1, 0.3, 1),
      flex 0.8s cubic-bezier(0.16, 1, 0.3, 1),
      transform 0.8s cubic-bezier(0.16, 1, 0.3, 1),
      opacity 0.6s ease;
  }

  .fur-hero {
    clip-path: inset(0 0 0 0);
    transition: width 0.8s cubic-bezier(0.16, 1, 0.3, 1),
      flex 0.8s cubic-bezier(0.16, 1, 0.3, 1),
      transform 0.8s cubic-bezier(0.16, 1, 0.3, 1),
      opacity 0.6s ease,
      clip-path 0.8s cubic-bezier(0.16, 1, 0.3, 1);
  }

  .fur-main {
    transition: width 0.8s cubic-bezier(0.16, 1, 0.3, 1),
      flex 0.8s cubic-bezier(0.16, 1, 0.3, 1);
  }

  /* Scrolled State - Hide Sidebar & Hero, Expand Main Feed to 100vw */
  body[data-scrolled="true"] .fur-sidebar {
    width: 0px !important;
    flex: 0 0 0px !important;
    padding-inline: 0 !important;
    border-inline-end-width: 0px !important;
    transform: translateX(-100%);
    opacity: 0;
    pointer-events: none;
  }

  body[data-scrolled="true"] [dir="rtl"] .fur-sidebar {
    transform: translateX(100%);
  }

  body[data-scrolled="true"] .fur-hero {
    width: 0px !important;
    flex: 0 0 0px !important;
    padding-inline: 0 !important;
    opacity: 0;
    transform: scale(0.95) translateX(-50px);
    clip-path: inset(0 100% 0 0);
    pointer-events: none;
  }

  body[data-scrolled="true"] [dir="rtl"] .fur-hero {
    transform: scale(0.95) translateX(50px);
    clip-path: inset(0 0 0 100%);
  }

  body[data-scrolled="true"] .fur-main {
    width: 100vw !important;
    flex: 0 0 100vw !important;
  }

  /* Update sliding drawer start point when sidebar disappears */
  body[data-scrolled="true"] .fur-sidebar__nav {
    inset-inline-start: 0;
    transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
  }

  body[data-scrolled="true"] .fur-sidebar__nav--open {
    transform: translateX(0) !important;
  }

  /* Sticky Top Header Scrolled Brand Styles */
  .fur-header__scrolled-brand {
    display: none;
    align-items: center;
    gap: 16px;
  }

  .fur-header__scrolled-toggle {
    background: transparent;
    border: none;
    cursor: pointer;
    color: var(--fur-text);
    padding: 8px;
    border-radius: var(--fur-radius-full);
    display: flex;
    justify-content: center;
    align-items: center;
    transition: background-color var(--fur-transition-normal);
  }

  .fur-header__scrolled-toggle:hover {
    background-color: var(--fur-border-light);
  }

  .fur-header__scrolled-logo {
    font-family: var(--fur-font-serif);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--fur-text);
    text-decoration: none;
  }

  body[data-scrolled="true"] .fur-header__scrolled-brand {
    display: flex !important;
  }

  body[data-scrolled="true"] .fur-header__ticker {
    display: none !important;
  }

  body[data-scrolled="true"] .fur-header {
    padding-inline: calc(var(--fur-margin-block-md) + 24px);
    box-shadow: 0 4px 30px var(--fur-shadow);
  }
}

/* ==========================================================================
   SCROLLED LAYOUT PRODUCT & ROOM GRID COLUMN OVERRIDES (APPENDED)
   ========================================================================== */
@media (min-width: 1025px) {

  /* Expand product grid to 4 columns in scrolled state, overriding the 2-column mobile/tablet rules */
  body[data-scrolled="true"] .fur-products__grid {
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 24px !important;
  }

  /* Room category grid expands to 3 columns in scrolled state */
  body[data-scrolled="true"] .fur-rooms-grid__layout {
    grid-template-columns: repeat(3, 1fr) !important;
    gap: 24px !important;
  }

  /* Style grid expands to 4 columns in scrolled state */
  body[data-scrolled="true"] .fur-styles__grid {
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 20px !important;
  }
}

@media (min-width: 1025px) and (max-width: 1400px) {

  /* 3 columns on medium sized desktop viewports when full screen */
  body[data-scrolled="true"] .fur-products__grid {
    grid-template-columns: repeat(3, 1fr) !important;
  }
}

/* ==========================================================================
   WEBGL CANVAS CONTAINER STYLING
