  display: none;
  /* Hidden on mobile/tablet viewports by default */
}

@media (min-width: 1025px) {
  body[data-scrolled="true"] .fur-header__scrolled-nav {
    display: flex;
    align-items: center;
    gap: 32px;
    margin-inline-start: 40px;
  }

  body[data-scrolled="true"] .fur-header__scrolled-toggle {
    display: none !important;
    /* Hide hamburger icon in scrolled state on desktop */
  }
}

.fur-header__scrolled-nav-link {
  font-family: var(--fur-font-sans);
  font-size: var(--fur-fs-small);
  font-weight: 600;
  color: var(--fur-text);
  transition: color var(--fur-transition-fast);
  text-decoration: none;
}

.fur-header__scrolled-nav-link:hover {
  color: var(--fur-primary);
}

/* ==========================================================================
   SCROLLED LAYOUT PROMO SLIDER TALLER HEIGHT
   ========================================================================== */
@media (min-width: 1025px) {
  body[data-scrolled="true"] .fur-promo__slider {
    height: 580px !important;
    /* Large desktop cinematic height */
    transition: height var(--fur-transition-slow);
  }
}

/* ==========================================================================
   INTERACTIVE LOOKBOOKS (TABS WITH HOTSPOTS) STYLING
   ========================================================================== */
.fur-lookbooks {
  padding-inline: 0;
  margin-block-start: var(--fur-margin-block-lg);
  margin-block-end: var(--fur-margin-block-lg);
}

.fur-lookbooks__tabs {
  display: flex;
  gap: 12px;
  margin-block-start: 12px;
}

.fur-lookbooks__tab {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  padding-inline: 20px;
  padding-block: 10px;
  border-radius: var(--fur-radius-full);
  font-family: var(--fur-font-sans);
  font-size: var(--fur-fs-small);
  font-weight: 600;
  color: var(--fur-text-muted);
  transition: all var(--fur-transition-fast);
  cursor: pointer;
}

.fur-lookbooks__tab:hover {
  border-color: var(--fur-primary);
  color: var(--fur-text);
