/* ==========================================================================
   PHASE 2 FIX: ULTRA-SMOOTH ORGANIC HERO DISSOLVE TRANSITION (OVERRIDE)
   ========================================================================== */
@media (min-width: 1025px) {

  /* Extend transition duration for a cinematic, organic feel */
  .fur-sidebar {
    transition: width 1.2s cubic-bezier(0.77, 0, 0.175, 1),
      flex 1.2s cubic-bezier(0.77, 0, 0.175, 1),
      opacity 0.9s ease,
      transform 1.2s cubic-bezier(0.77, 0, 0.175, 1) !important;
  }

  .fur-hero {
    will-change: opacity, transform, flex, clip-path;
    clip-path: inset(0 0% 0 0);
    transition: flex 1.2s cubic-bezier(0.77, 0, 0.175, 1),
      width 1.2s cubic-bezier(0.77, 0, 0.175, 1),
      opacity 0.8s ease 0.1s,
      transform 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      clip-path 1.0s cubic-bezier(0.77, 0, 0.175, 1) !important;
  }

  .fur-main {
    transition: flex 1.2s cubic-bezier(0.77, 0, 0.175, 1),
      width 1.2s cubic-bezier(0.77, 0, 0.175, 1) !important;
  }

  /* Smooth organic dissolve: fade + gentle slide left + clip */
  body[data-scrolled="true"] .fur-hero {
    flex: 0 0 0vw !important;
    width: 0vw !important;
    opacity: 0 !important;
    transform: scale(0.97) translateX(-30px) !important;
    clip-path: inset(0 100% 0 0) !important;
    padding-inline: 0 !important;
    pointer-events: none !important;
    border-inline-end-width: 0 !important;
    overflow: hidden !important;
  }

  body[data-scrolled="true"] .fur-sidebar {
    flex: 0 0 0px !important;
    width: 0px !important;
    opacity: 0 !important;
    transform: translateX(-110%) !important;
    padding-inline: 0 !important;
    border-inline-end-width: 0 !important;
    pointer-events: none !important;
    overflow: hidden !important;
  }

  body[data-scrolled="true"] .fur-main {
    flex: 0 0 100vw !important;
    width: 100vw !important;
    max-width: 100vw !important;
  }

  /* Product grid always 4 columns in scrolled desktop state */
  body[data-scrolled="true"] .fur-products__grid {
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 24px !important;
  }

  /* Category scroller visible in BOTH states - never hide it */
  body[data-scrolled="true"] .fur-categories {
    display: block !important;
    opacity: 1 !important;
    visibility: visible !important;
  }
}

/* Fix: categories always visible on all viewports */
.fur-categories {
  display: block !important;
}

