}

.fur-stats__unit {
  font-size: clamp(1.2rem, 2vw, 1.8rem);
  font-weight: 700;
  color: hsla(0, 0%, 100%, 0.6);
}

.fur-stats__label {
  display: block;
  font-size: var(--fur-fs-small);
  color: hsla(0, 0%, 100%, 0.7);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-block-start: 6px;
}

.fur-stats__divider {
  width: 1px;
  height: 60px;
  background-color: hsla(0, 0%, 100%, 0.2);
  flex-shrink: 0;
}

/* TESTIMONIALS */
.fur-testimonials {
  padding-inline: var(--fur-margin-block-md);
  padding-block: var(--fur-margin-block-lg);
  background-color: var(--fur-bg-secondary);
  overflow: hidden;
}

.fur-testimonials__header {
  text-align: center;
  margin-block-end: clamp(2rem, 3vw, 3.5rem);
}

.fur-testimonials__tag {
  font-size: var(--fur-fs-small);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--fur-primary);
}

.fur-testimonials__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h2);
  color: var(--fur-text);
  margin-block-start: 8px;
  margin-block-end: 0;
}

.fur-testimonials__title em {
  font-style: italic;
  color: var(--fur-primary);
}

.fur-testimonials__track {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.fur-testimonial-card {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-lg);
  padding: clamp(20px, 2.5vw, 32px);
  display: flex;
  flex-direction: column;
  gap: 16px;
