  border-color: var(--fur-primary);
}

.fur-testimonial-card__stars {
  font-size: 1rem;
  color: hsl(42, 96%, 52%);
  letter-spacing: 2px;
}

.fur-testimonial-card__quote {
  font-size: var(--fur-fs-body);
  color: var(--fur-text);
  line-height: 1.7;
  font-style: italic;
  margin: 0;
  flex: 1;
}

.fur-testimonial-card__author {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block-start: 16px;
  border-block-start: 1px solid var(--fur-border);
}

.fur-testimonial-card__avatar {
  width: 42px;
  height: 42px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  font-size: 1rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.fur-testimonial-card__author strong {
  display: block;
  font-size: var(--fur-fs-body);
  color: var(--fur-text);
}

.fur-testimonial-card__author span {
  display: block;
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
}

.fur-testimonials__controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-block-start: 2rem;
}

.fur-testimonials__arrow {
  width: 44px;
  height: 44px;
  border-radius: var(--fur-radius-full);
  border: 1px solid var(--fur-border);
  background-color: var(--fur-surface);
  color: var(--fur-text);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--fur-transition-normal);
}

.fur-testimonials__arrow:hover {
  background-color: var(--fur-primary);
  border-color: var(--fur-primary);
  color: var(--fur-button-text);
}

/* JOURNAL GRID (NEW EDITORIAL LAYOUT) */
.fur-journal {
  padding-inline: var(--fur-margin-block-md);
  padding-block: var(--fur-margin-block-lg);
}

.fur-journal__grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 24px;
}

.fur-journal__card {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  transition: all var(--fur-transition-normal);
  display: flex;
  flex-direction: column;
}

.fur-journal__card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 36px var(--fur-shadow-lg);
  border-color: var(--fur-primary);
}

.fur-journal__card-img-wrap {
  position: relative;
  overflow: hidden;
}

.fur-journal__card--featured .fur-journal__card-img-wrap {
  height: 280px;
}

.fur-journal__card-img-wrap:not(.fur-journal__card--featured .fur-journal__card-img-wrap) {
