}

.fur-journal__card-tag {
  position: absolute;
  inset-block-start: 14px;
  inset-inline-start: 14px;
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding-inline: 12px;
  padding-block: 5px;
  border-radius: var(--fur-radius-full);
}

.fur-journal__card-body {
  padding: clamp(16px, 2vw, 24px);
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
}

.fur-journal__card-date {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
}

.fur-journal__card-title {
  font-family: var(--fur-font-serif);
  font-size: clamp(1rem, 1.4vw, 1.3rem);
  color: var(--fur-text);
  line-height: 1.35;
  margin: 0;
}

.fur-journal__card-excerpt {
  font-size: var(--fur-fs-small);
  color: var(--fur-text-muted);
  line-height: 1.65;
  margin: 0;
}

.fur-journal__card-link {
