  font-weight: 700;
  color: var(--fur-primary);
  text-decoration: none;
  margin-block-start: auto;
  padding-block-start: 8px;
  transition: gap var(--fur-transition-fast);
}

.fur-journal__card-link:hover {
  text-decoration: underline;
}

/* NEWSLETTER SECTION */
.fur-newsletter {
  margin-inline: var(--fur-margin-block-md);
  margin-block: var(--fur-margin-block-lg);
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  background: linear-gradient(135deg, var(--fur-ref-green-900) 0%, var(--fur-ref-green-700) 100%);
}

.fur-newsletter__inner {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  min-height: 360px;
}

.fur-newsletter__content {
  padding: clamp(2.5rem, 5vw, 5rem);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.fur-newsletter__tag {
  font-size: var(--fur-fs-small);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: hsla(0, 0%, 100%, 0.65);
}

.fur-newsletter__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.5rem, 2.5vw, 2.2rem);
  color: var(--fur-ref-white);
  margin: 0;
  line-height: 1.3;
}

.fur-newsletter__desc {
  font-size: var(--fur-fs-body);
  color: hsla(0, 0%, 100%, 0.75);
  margin: 0;
  line-height: 1.65;
}

.fur-newsletter__label {
  font-size: var(--fur-fs-small);
  font-weight: 600;
  color: hsla(0, 0%, 100%, 0.8);
  display: block;
  margin-block-end: 6px;
}

.fur-newsletter__input-group {
  display: flex;
  gap: 0;
  border-radius: var(--fur-radius-full);
