/* PREMIUM FOOTER */
.fur-footer {
  background-color: var(--fur-ref-charcoal);
  color: var(--fur-ref-beige-100);
  padding-block-end: 0;
}

.fur-footer__top {
  display: grid;
  grid-template-columns: 1.4fr 2fr 0.9fr;
  gap: clamp(2rem, 4vw, 5rem);
  padding-inline: var(--fur-margin-block-md);
  padding-block: clamp(3rem, 5vw, 5rem);
  border-block-end: 1px solid hsla(0, 0%, 100%, 0.08);
}

.fur-footer__logo {
  font-family: var(--fur-font-serif);
  font-size: 2.2rem;
  font-weight: 700;
  color: var(--fur-ref-white);
  text-decoration: none;
  line-height: 1;
  display: block;
  margin-block-end: 14px;
}

.fur-footer__logo-dot {
  color: var(--fur-ref-lime-400);
}

.fur-footer__tagline {
  font-size: var(--fur-fs-small);
  color: hsla(0, 0%, 100%, 0.5);
  line-height: 1.7;
  margin: 0;
  margin-block-end: 20px;
}

.fur-footer__socials {
  display: flex;
  gap: 10px;
}

.fur-footer__social-link {
  width: 38px;
  height: 38px;
  border-radius: var(--fur-radius-full);
  border: 1px solid hsla(0, 0%, 100%, 0.15);
  color: hsla(0, 0%, 100%, 0.6);
  display: flex;
  align-items: center;
