}

.fur-footer__col-list a:hover {
  color: var(--fur-ref-white);
}

.fur-footer__trust-col .fur-footer__col-heading {
  margin-block-end: 16px;
}

.fur-footer__trust-badges {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.fur-footer__trust-badge {
