  align-items: center;
  gap: 10px;
  font-size: var(--fur-fs-small);
  color: hsla(0, 0%, 100%, 0.55);
}

.fur-footer__trust-badge svg {
  color: var(--fur-ref-lime-400);
  flex-shrink: 0;
}

.fur-footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding-inline: var(--fur-margin-block-md);
  padding-block: 20px;
  background-color: hsla(0, 0%, 0%, 0.3);
}

.fur-footer__copy {
  font-size: var(--fur-fs-small);
  color: hsla(0, 0%, 100%, 0.35);
  margin: 0;
}

.fur-footer__legal {
  display: flex;
  gap: 20px;
}

.fur-footer__legal a {
  font-size: var(--fur-fs-small);
  color: hsla(0, 0%, 100%, 0.35);
  text-decoration: none;
  transition: color var(--fur-transition-fast);
}

.fur-footer__legal a:hover {
  color: var(--fur-ref-white);
}

/* Dark theme footer adjustments */
body[data-theme="dark"] .fur-footer {
  background-color: var(--fur-ref-forest-950);
}

/* RESPONSIVE: New sections */
@media (max-width: 1024px) {
