   ========================================================================== */

/* 1. ADD MISSING TRANSITIONS TO SIDEBAR & HERO ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â was only transitioning bg-color!
      Must be in the same @media block as the scrolled state rules */
@media (min-width: 1025px) {

  /* Sidebar gets full smooth transition on ALL transitioning properties */
  .fur-sidebar {
    transition: width 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      flex 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      transform 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      opacity 0.7s cubic-bezier(0.77, 0, 0.175, 1),
      padding-inline 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      border-color 0.5s ease,
      background-color 0.5s ease !important;
  }

  /* Hero panel: smooth scale + clip-path collapse */
  .fur-hero {
    transition: width 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      flex 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      transform 1.0s cubic-bezier(0.77, 0, 0.175, 1),
      opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1),
      clip-path 1.0s cubic-bezier(0.77, 0, 0.175, 1) !important;
  }

  /* Main feed expands smoothly */
  .fur-main {
    transition: width 1.1s cubic-bezier(0.77, 0, 0.175, 1),
      flex 1.1s cubic-bezier(0.77, 0, 0.175, 1) !important;
  }

  /* When scrolled state: main content fades in a beat AFTER sidebar collapses */
  body[data-scrolled="true"] .fur-main>* {
    animation: fur-content-appear 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.55s both;
  }

  @keyframes fur-content-appear {
    from {
      opacity: 0.6;
      transform: translateX(-16px);
    }

    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  /* Header scrolled brand drops in */
  body[data-scrolled="true"] .fur-header__scrolled-brand {
    animation: fur-header-drop-in 0.55s cubic-bezier(0.16, 1, 0.3, 1) 0.4s both;
  }

  @keyframes fur-header-drop-in {
    from {
      opacity: 0;
      transform: translateY(-12px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

