/* 3. Strip redundant base padding/margin from outer section wrappers */
.fur-promo,
.fur-categories,
.fur-rooms-grid,
.fur-styles,
.fur-products,
.fur-materials,
.fur-testimonials,
.fur-journal,
.fur-newsletter,
