  margin-block-end: 12px;
}

.fur-journal-sound__comp-row {
  display: flex;
  gap: 10px;
}

.fur-journal-sound__comp-btn {
  flex: 1;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  color: var(--fur-text);
  padding: 8px 12px;
  border-radius: 4px;
