}

.fur-journal-sound__mini-feedback {
  margin-block-start: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  padding: 6px 12px;
  border-radius: 4px;
}

.fur-sound-feedback-txt {
  font-size: 0.68rem;
  font-weight: 500;
