}

.fur-journal-sound__meta-title {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--fur-text);
  display: block;
}

.fur-journal-sound__meta-desc {
  font-size: 0.7rem;
  color: var(--fur-text-muted);
}

/* Section 5 Polish - Registry of Stockists */
.fur-journal-stockists__row {
  position: relative;
  transition: background-color 0.3s ease;
}

.fur-stock-city-label {
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fur-text);
