  font-size: 0.72rem;
  font-weight: 500;
  color: var(--fur-primary);
  margin-block-start: 4px;
}

.fur-stock-action-btn {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  color: var(--fur-text);
  padding: 8px 20px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.fur-stock-action-btn:hover {
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  border-color: var(--fur-primary);
  box-shadow: var(--fur-shadow-sm);
}

/* Floating interactive showroom mouse preview widget */
.fur-stock-hover-preview {
  position: fixed;
  pointer-events: none;
  z-index: 9999;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  padding: 4px;
  border-radius: var(--fur-radius-sm);
  box-shadow: var(--fur-shadow-lg);
  opacity: 0;
  transform: scale(0.9) translate(-50%, -110%);
  transition: opacity 0.25s cubic-bezier(0.16, 1, 0.3, 1), transform 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}

.fur-stock-hover-preview--visible {
  opacity: 1;
  transform: scale(1) translate(-50%, -110%);
}

.fur-stock-hover-preview img {
  display: block;
  border-radius: calc(var(--fur-radius-sm) - 2px);
  object-fit: cover;
}

/* ==========================================================================
   TFT JOURNAL EDITION - HOME 4 REFINEMENTS
   ========================================================================== */

/* 1. Bespoke mobile overlay menu */
.tft-jnl-menu {
  position: fixed;
  inset: 0;
  z-index: 99999;
  background-color: var(--fur-bg);
  backdrop-filter: blur(20px);
