  letter-spacing: -0.02em;
}

.tft-jnl-menu__subtitle {
  font-family: var(--fur-font-sans);
  font-size: clamp(0.7rem, 2vw, 0.9rem);
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--fur-text-muted);
  font-weight: 600;
  padding-bottom: 4px;
}

.tft-jnl-menu__nav {
  margin-block: auto;
}

.tft-jnl-menu__list {
  list-style: none;
