  width: 100%;
  height: 100%;
  object-fit: cover;
  position: absolute;
  inset: 0;
  transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.tft-jnl-palette__display-caption {
  position: relative;
  z-index: 2;
  padding: clamp(20px, 4vw, 30px);
  background: linear-gradient(to top, rgba(0, 0, 0, 0.8) 0%, rgba(0, 0, 0, 0.4) 60%, transparent 100%);
  color: var(--fur-bg);
  width: 100%;
  box-sizing: border-box;
}

.tft-jnl-palette__display-caption h4 {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.2rem, 3.5vw, 1.6rem);
  font-weight: 400;
  margin-block-end: 6px;
  color: var(--fur-bg);
}

.tft-jnl-palette__display-caption p {
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.85);
  margin: 0;
}





/* ==========================================================================
   THEMEFOREST COMPATIBILITY: WIDE INNER PAGES RECTIFICATION
   ========================================================================== */
@media (min-width: 1025px) {

  /* Expand the main content feed to occupy all remaining width on all inner pages */
  .tft-layout-wide .fur-main {
    flex: 1 !important;
    width: auto !important;
    max-width: none !important;
  }
}

/* ==========================================================================
   THEMEFOREST & WP-CONVERSION: PREMIUM INNER PAGES POLISH & DECORATIONS
   ========================================================================== */

/* 1. Immersive Ken Burns Header Block */
.tft-page-header {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  min-block-size: clamp(300px, 35vh, 420px);
  overflow: hidden;
  margin-block-end: var(--fur-margin-block-lg);
  border-radius: var(--fur-radius-lg);
  padding-inline: var(--fur-margin-block-md);
  padding-block: var(--fur-margin-block-lg);
  color: var(--fur-ref-white);
  box-shadow: 0 10px 40px var(--fur-shadow-lg);
}

.tft-page-header__bg-wrap {
  position: absolute;
  inset: 0;
  z-index: 1;
  overflow: hidden;
}

.tft-page-header__bg-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: tft-kenburns-zoom 35s ease-in-out infinite alternate;
}

.tft-page-header__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom,
      color-mix(in srgb, var(--fur-primary) 30%, transparent) 0%,
      color-mix(in srgb, var(--fur-primary) 85%, transparent) 100%);
  z-index: 2;
}

.tft-page-header__container {
  position: relative;
  z-index: 3;
  max-width: 900px;
  width: 100%;
  margin-inline: auto;
  text-align: left;
}

.tft-page-header__tag {
  display: inline-block;
  font-family: var(--fur-font-sans);
  font-size: clamp(0.75rem, 1.2vw, 0.85rem);
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-weight: 700;
  color: var(--fur-bg);
  background-color: color-mix(in srgb, var(--fur-primary) 40%, transparent);
  padding-inline: 12px;
  padding-block: 4px;
  border-radius: var(--fur-radius-sm);
  margin-block-end: 16px;
  border: 1px solid color-mix(in srgb, var(--fur-bg) 30%, transparent);
}

.tft-page-header__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(2rem, 5vw, 3.8rem);
  line-height: 1.15;
  font-weight: 300;
  color: var(--fur-ref-white);
  margin-block-end: 16px;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.2);
}

.tft-page-header__desc {
  font-family: var(--fur-font-sans);
  font-size: clamp(0.9rem, 1.5vw, 1.1rem);
  line-height: 1.6;
  font-weight: 300;
  color: color-mix(in srgb, var(--fur-ref-white) 80%, transparent);
  max-width: 650px;
}

@keyframes tft-kenburns-zoom {
  0% {
    transform: scale(1) translate(0, 0);
  }

  100% {
    transform: scale(1.12) translate(-1%, -0.5%);
  }
}

/* 2. Shop Page: Hotspot Lookbook */
.tft-lookbook {
  position: relative;
  margin-block: var(--fur-margin-block-lg);
  border-radius: var(--fur-radius-xl);
  overflow: hidden;
  box-shadow: 0 12px 40px var(--fur-shadow-lg);
}

.tft-lookbook__img-wrap {
  width: 100%;
  aspect-ratio: 21 / 9;
  min-block-size: 280px;
  overflow: hidden;
}

.tft-lookbook__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tft-lookbook__hotspot {
  position: absolute;
  width: 24px;
  height: 24px;
  background-color: var(--fur-ref-white);
  border: 4px solid var(--fur-primary);
  border-radius: var(--fur-radius-full);
  cursor: pointer;
  z-index: 5;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 6px color-mix(in srgb, var(--fur-ref-white) 40%, transparent);
  transition: transform var(--fur-transition-fast), box-shadow var(--fur-transition-fast);
}

.tft-lookbook__hotspot:hover {
  transform: translate(-50%, -50%) scale(1.25);
  box-shadow: 0 0 0 10px color-mix(in srgb, var(--fur-primary) 30%, transparent);
}

.tft-lookbook__hotspot::after {
  content: "";
  position: absolute;
  inset: -12px;
  border-radius: var(--fur-radius-full);
  border: 1px solid var(--fur-ref-white);
  animation: tft-pulse 2s infinite;
  opacity: 0;
}

@keyframes tft-pulse {
  0% {
    transform: scale(0.6);
    opacity: 1;
  }

  100% {
    transform: scale(1.4);
    opacity: 0;
  }
}

.tft-lookbook__card {
  position: absolute;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  padding: 16px;
  width: 220px;
  box-shadow: 0 10px 30px var(--fur-shadow-lg);
  z-index: 10;
  opacity: 0;
  visibility: hidden;
  transform: translate(-50%, -120%) scale(0.95);
  transition: opacity var(--fur-transition-normal), transform var(--fur-transition-normal), visibility var(--fur-transition-normal);
}

.tft-lookbook__card--visible {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, -120%) scale(1);
}

.tft-lookbook__card-title {
  font-family: var(--fur-font-serif);
  font-size: 1rem;
  color: var(--fur-text);
  margin-block-end: 4px;
}

.tft-lookbook__card-price {
  font-family: var(--fur-font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--fur-primary);
  margin-block-end: 8px;
}

.tft-lookbook__card-link {
  font-family: var(--fur-font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fur-ref-white);
  background-color: var(--fur-primary);
  padding-inline: 12px;
  padding-block: 6px;
  border-radius: var(--fur-radius-sm);
  display: inline-block;
  transition: background-color var(--fur-transition-fast);
}

.tft-lookbook__card-link:hover {
  background-color: var(--fur-primary-hover);
}

/* 3. Shop Page: Material Swatch Showcase */
.tft-materials-sec {
  margin-block: var(--fur-margin-block-lg);
  padding: clamp(20px, 4vw, 40px);
  background-color: var(--fur-bg-secondary);
  border-radius: var(--fur-radius-xl);
  border: 1px solid var(--fur-border);
}

.tft-materials-sec__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h2);
  margin-block-end: 24px;
  text-align: center;
}

.tft-materials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}

.tft-materials-card {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  overflow: hidden;
  box-shadow: 0 4px 20px var(--fur-shadow);
  transition: transform var(--fur-transition-normal), box-shadow var(--fur-transition-normal);
}

.tft-materials-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px var(--fur-shadow-lg);
}

.tft-materials-card__img-wrap {
  width: 100%;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}

.tft-materials-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tft-materials-card__body {
  padding: 20px;
}

.tft-materials-card__tag {
  font-family: var(--fur-font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--fur-primary);
  margin-block-end: 8px;
  display: block;
}

.tft-materials-card__title {
  font-family: var(--fur-font-serif);
  font-size: 1.15rem;
  margin-block-end: 8px;
}

.tft-materials-card__desc {
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  color: var(--fur-text-muted);
  line-height: 1.6;
}

/* 4. Product Details: Accordions */
.tft-product-accordion {
  border-top: 1px solid var(--fur-border);
  margin-block-start: 24px;
}

.tft-product-accordion__item {
  border-bottom: 1px solid var(--fur-border);
}

.tft-product-accordion__btn {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-block: 16px;
  text-align: left;
  font-family: var(--fur-font-serif);
  font-size: 1.1rem;
  color: var(--fur-text);
  font-weight: 500;
}

.tft-product-accordion__btn .fur-icon {
  transition: transform var(--fur-transition-fast);
}

.tft-product-accordion__btn[aria-expanded="true"] .fur-icon {
  transform: rotate(180deg);
}

.tft-product-accordion__panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--fur-transition-normal) ease-out;
}

.tft-product-accordion__content {
  padding-block-end: 16px;
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  color: var(--fur-text-muted);
  line-height: 1.6;
}

/* 5. Product Details: Scarcity Ticker & Timeline */
.tft-scarcity-ticker {
  background-color: color-mix(in srgb, var(--fur-accent) 8%, transparent);
  border: 1px dashed var(--fur-accent);
  padding: 12px 16px;
  border-radius: var(--fur-radius-sm);
  display: flex;
  align-items: center;
  gap: 12px;
  margin-block: 16px;
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  color: var(--fur-accent);
  font-weight: 600;
}

.tft-scarcity-ticker__dot {
  width: 8px;
  height: 8px;
  background-color: var(--fur-accent);
  border-radius: var(--fur-radius-full);
  animation: tft-dot-pulse 1.5s infinite alternate;
}

@keyframes tft-dot-pulse {
  0% {
    opacity: 0.4;
  }

  100% {
    opacity: 1;
  }
}

.tft-configurator-timeline {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background-color: var(--fur-bg-secondary);
  border-radius: var(--fur-radius-md);
  padding: 16px;
  border: 1px solid var(--fur-border);
  margin-block-start: 16px;
}

.tft-configurator-timeline__step {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.tft-configurator-timeline__icon {
  width: 20px;
  height: 20px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fur-ref-white);
  font-size: 0.65rem;
  font-weight: 800;
  flex-shrink: 0;
  margin-block-start: 2px;
}

.tft-configurator-timeline__step-title {
  font-family: var(--fur-font-sans);
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--fur-text);
  margin-block-end: 2px;
}

.tft-configurator-timeline__step-desc {
  font-family: var(--fur-font-sans);
  font-size: 0.75rem;
  color: var(--fur-text-muted);
}

/* 6. About Us: Artisans & Stats */
.tft-artisans-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  margin-block: var(--fur-margin-block-lg);
}

.tft-artisans-card {
  text-align: center;
}

.tft-artisans-card__img-wrap {
  width: 160px;
  height: 160px;
  border-radius: var(--fur-radius-full);
  overflow: hidden;
  margin-inline: auto;
  margin-block-end: 20px;
  border: 3px solid var(--fur-border);
  box-shadow: 0 4px 15px var(--fur-shadow);
}

.tft-artisans-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tft-artisans-card__name {
  font-family: var(--fur-font-serif);
  font-size: 1.25rem;
  margin-block-end: 4px;
}

.tft-artisans-card__role {
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--fur-primary);
  margin-block-end: 12px;
  display: block;
}

.tft-artisans-card__bio {
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  color: var(--fur-text-muted);
  line-height: 1.5;
}

.tft-sustainability-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
  padding: 40px;
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  border-radius: var(--fur-radius-xl);
  text-align: center;
  margin-block: var(--fur-margin-block-lg);
}

.tft-sustainability-stats__val {
  font-family: var(--fur-font-serif);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 300;
  margin-block-end: 8px;
  color: var(--fur-bg);
}

.tft-sustainability-stats__label {
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: color-mix(in srgb, var(--fur-ref-white) 80%, transparent);
}

/* 7. Contact Us: Calendar Slots & Accordions */
.tft-calendar-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-block: 16px;
}

.tft-calendar-slot {
  background-color: var(--fur-bg-secondary);
  border: 1px solid var(--fur-border);
  padding: 12px;
  border-radius: var(--fur-radius-sm);
  text-align: center;
  cursor: pointer;
  transition: all var(--fur-transition-fast);
}

.tft-calendar-slot:hover {
  border-color: var(--fur-primary);
  background-color: var(--fur-sidebar-active);
}

.tft-calendar-slot--selected {
  border-color: var(--fur-primary);
  background-color: var(--fur-primary);
  color: var(--fur-ref-white) !important;
}

.tft-calendar-slot__day {
  font-family: var(--fur-font-sans);
  font-weight: 700;
  font-size: 0.75rem;
  text-transform: uppercase;
  margin-block-end: 4px;
}

.tft-calendar-slot__time {
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  font-weight: 600;
}

.tft-faq-accordion {
  margin-block-start: 40px;
}

.tft-faq-accordion__title {
  font-family: var(--fur-font-serif);
  font-size: var(--fur-fs-h3);
  margin-block-end: 20px;
}

/* 8. Blog: Scroll Indicator & Audio Podcast */
.tft-scroll-progress {
  position: fixed;
  inset-block-start: 0;
  inset-inline: 0;
  block-size: 4px;
  background-color: var(--fur-border);
  z-index: 1000;
}

.tft-scroll-progress__bar {
  block-size: 100%;
  inline-size: 0%;
  background-color: var(--fur-accent);
  transition: width 0.1s ease-out;
}

.tft-podcast-widget {
  background-color: var(--fur-bg-secondary);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 16px;
  margin-block-end: 24px;
}

.tft-podcast-widget__play-btn {
  width: 48px;
  height: 48px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--fur-transition-fast), background-color var(--fur-transition-fast);
}

.tft-podcast-widget__play-btn:hover {
  transform: scale(1.05);
  background-color: var(--fur-primary-hover);
}

.tft-podcast-widget__track-info {
  flex: 1;
}

.tft-podcast-widget__title {
  font-family: var(--fur-font-sans);
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--fur-text);
}

.tft-podcast-widget__desc {
  font-family: var(--fur-font-sans);
  font-size: 0.75rem;
  color: var(--fur-text-muted);
}

.tft-podcast-widget__progress-container {
  width: 100%;
  height: 4px;
  background-color: var(--fur-border);
  border-radius: var(--fur-radius-full);
  margin-block-start: 8px;
  overflow: hidden;
}

.tft-podcast-widget__progress-bar {
  width: 0%;
  height: 100%;
  background-color: var(--fur-primary);
  transition: width 0.3s ease;
}

/* 9. Checkout: Transit Stepper */
.tft-shipping-stepper {
  display: flex;
  justify-content: space-between;
  position: relative;
  margin-block: 40px;
}

.tft-shipping-stepper::before {
  content: "";
  position: absolute;
  inset-block-start: 14px;
  inset-inline: 0;
  height: 2px;
  background-color: var(--fur-border);
  z-index: 1;
}

.tft-shipping-stepper__step {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  z-index: 2;
  flex: 1;
  text-align: center;
}

.tft-shipping-stepper__indicator {
  width: 30px;
  height: 30px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-surface);
  border: 2px solid var(--fur-border);
  color: var(--fur-text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  font-weight: 700;
  margin-block-end: 8px;
  transition: all var(--fur-transition-normal);
}

.tft-shipping-stepper__step--active .tft-shipping-stepper__indicator {
  background-color: var(--fur-primary);
  border-color: var(--fur-primary);
  color: var(--fur-ref-white);
  box-shadow: 0 0 0 6px color-mix(in srgb, var(--fur-primary) 20%, transparent);
}

.tft-shipping-stepper__step--complete .tft-shipping-stepper__indicator {
  background-color: var(--fur-primary);
  border-color: var(--fur-primary);
  color: var(--fur-ref-white);
}

.tft-shipping-stepper__label {
  font-family: var(--fur-font-sans);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--fur-text-muted);
}

.tft-shipping-stepper__step--active .tft-shipping-stepper__label {
  color: var(--fur-text);
}

/* ==========================================================================
   PRODUCT SINGLE PAGE PREMIUM LAYOUT & 3D SWITCH SHOWCASE
   ========================================================================== */
.tft-single-product-wrap {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 48px;
  width: 100%;
  margin-block-end: 80px;
}

@media (max-width: 991px) {
  .tft-single-product-wrap {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}

.tft-single-showcase {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-xl);
  padding: 0;
  display: flex;
  flex-direction: column;
  align-self: start;
  position: sticky;
  top: 100px;
  overflow: hidden;
}

.tft-single-showcase__view {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: auto;
  transition: opacity 0.3s ease;
}

.tft-single-showcase__view--hidden {
  display: none !important;
}

/* ------------------------------------------------------------------------
   14. INTERACTIVE DESIGN STUDIO CALL TO ACTION
   ------------------------------------------------------------------------ */
.tft-planner-cta {
  padding-block: var(--fur-margin-block-lg);
  padding-inline: var(--fur-margin-block-md);
  max-width: 1400px;
  margin-inline: auto;
  width: 100%;
}

.tft-planner-cta__wrapper {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-xl);
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: clamp(2rem, 4vw, 5rem);
  padding-inline: clamp(2rem, 3.5vw, 4.5rem);
  padding-block: clamp(2rem, 3.5vw, 4.5rem);
  align-items: center;
  box-shadow: 0 10px 30px var(--fur-shadow);
  overflow: hidden;
}

@media (max-width: 991px) {
  .tft-planner-cta__wrapper {
    grid-template-columns: 1fr;
    gap: 32px;
    padding-inline: 24px;
    padding-block: 40px;
  }
}

.tft-planner-cta__content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
}

.tft-planner-cta__tag {
  display: inline-block;
  font-size: var(--fur-fs-small);
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--fur-primary);
  font-weight: 700;
}

.tft-planner-cta__title {
