    visibility: visible !important;
  }

  /* Reset default fadeInUp animation */
  .fur-sidebar__nav--open {
    animation: none !important;
  }

  /* Nav Links styling for drawer */
  .fur-sidebar__nav-list {
    display: flex !important;
    flex-direction: column !important;
    gap: 20px !important;
    margin-block-start: 40px !important;
  }

  .fur-sidebar__nav-item {
    opacity: 0 !important;
    transform: translateY(20px) !important;
    transition: opacity 0.4s ease, transform 0.4s ease !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item {
    opacity: 1 !important;
    transform: translateY(0) !important;
  }

  /* Stagger delays for 8 items */
  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(1) {
    transition-delay: 0.1s !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(2) {
    transition-delay: 0.15s !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(3) {
    transition-delay: 0.2s !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(4) {
    transition-delay: 0.25s !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(5) {
    transition-delay: 0.3s !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(6) {
    transition-delay: 0.35s !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(7) {
    transition-delay: 0.4s !important;
  }

  .fur-sidebar__nav--open .fur-sidebar__nav-item:nth-child(8) {
    transition-delay: 0.45s !important;
  }

  /* Premium Close Button inside drawer for mobile */
  .fur-sidebar__nav-close {
    display: flex !important;
    align-self: flex-end !important;
    background: none !important;
    border: none !important;
    color: var(--fur-text) !important;
    cursor: pointer !important;
    padding: 8px !important;
    margin-inline-end: -8px !important;
    margin-block-end: 20px !important;
    transition: transform 0.3s ease !important;
  }

