/* ==========================================================================
   2026 PREMIUM REDESIGNED EDITORIAL FOOTER & HEADER DRAWER SYNC
   ========================================================================== */

/* 1. Header Sidebar Drawer Overrides (Cutoff Fix) */
.fur-sidebar__nav {
  z-index: 1100 !important;
  padding-block-start: 80px !important;
}

/* 2. Redesigned Editorial Footer */
.tft-footer {
  background-color: var(--fur-bg-secondary) !important;
  border-block-start: 1px solid var(--fur-border) !important;
  padding-inline: var(--fur-margin-block-md) !important;
  padding-block: clamp(40px, 6vw, 80px) clamp(20px, 4vw, 40px) !important;
  margin-block-start: auto !important;
  transition: all var(--fur-transition-normal) !important;
  font-family: var(--fur-font-sans) !important;
}

.tft-footer__container {
  max-width: 1400px !important;
  margin-inline: auto !important;
}

.tft-footer__grid {
  display: grid !important;
  grid-template-columns: 1.5fr repeat(3, 1fr) 1.5fr !important;
  gap: clamp(24px, 3vw, 48px) !important;
  margin-block-end: clamp(32px, 5vw, 64px) !important;
}

@media (max-width: 1024px) {
  .tft-footer__grid {
    grid-template-columns: repeat(2, 1fr) !important;
  }

  .tft-footer__col-brand,
  .tft-footer__col-newsletter {
    grid-column: span 2 !important;
  }
}

@media (max-width: 600px) {
  .tft-footer__grid {
    grid-template-columns: 1fr !important;
  }

  .tft-footer__col-brand,
  .tft-footer__col-newsletter {
    grid-column: span 1 !important;
  }
}

/* Brand Column styling */
.tft-footer__col-brand {
  display: flex !important;
  flex-direction: column !important;
  gap: 16px !important;
}

.tft-footer__logo {
  font-family: var(--fur-font-sans) !important;
  font-weight: 800 !important;
  font-size: 2.2rem !important;
  letter-spacing: -2px !important;
  color: var(--fur-text) !important;
  text-decoration: none !important;
  line-height: 1 !important;
}

.tft-footer__logo-dot {
  color: var(--fur-primary) !important;
}

.tft-footer__brand-desc {
  font-size: var(--fur-fs-small) !important;
  color: var(--fur-text-muted) !important;
  line-height: 1.6 !important;
  margin: 0 !important;
}

.tft-footer__address {
  font-style: normal !important;
  font-size: var(--fur-fs-small) !important;
  color: var(--fur-text-muted) !important;
  line-height: 1.5 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 6px !important;
}

.tft-footer__social-list {
  display: flex !important;
  gap: 16px !important;
  margin-block-start: 8px !important;
  padding: 0 !important;
  list-style: none !important;
}

.tft-footer__social-link {
  font-size: var(--fur-fs-small) !important;
  color: var(--fur-text-muted) !important;
  text-decoration: none !important;
  transition: color var(--fur-transition-fast) !important;
}

.tft-footer__social-link:hover {
  color: var(--fur-primary) !important;
}

/* Link Columns */
.tft-footer__col-links {
  display: flex !important;
  flex-direction: column !important;
  gap: 20px !important;
}

.tft-footer__heading {
  font-family: var(--fur-font-sans) !important;
  font-weight: 600 !important;
  font-size: var(--fur-fs-small) !important;
  text-transform: uppercase !important;
  letter-spacing: 0.08em !important;
  color: var(--fur-text) !important;
  margin: 0 !important;
}

.tft-footer__list {
  list-style: none !important;
  padding: 0 !important;
  margin: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 12px !important;
}

.tft-footer__list a {
  font-size: var(--fur-fs-small) !important;
  color: var(--fur-text-muted) !important;
  text-decoration: none !important;
  transition: all var(--fur-transition-fast) !important;
  display: inline-block !important;
}

.tft-footer__list a:hover {
  color: var(--fur-primary) !important;
  transform: translateX(4px) !important;
}

[dir="rtl"] .tft-footer__list a:hover {
  transform: translateX(-4px) !important;
}

/* Newsletter Dispatch Column */
.tft-footer__col-newsletter {
  display: flex !important;
  flex-direction: column !important;
  gap: 16px !important;
}

.tft-footer__newsletter-desc {
  font-size: var(--fur-fs-small) !important;
  color: var(--fur-text-muted) !important;
  line-height: 1.6 !important;
  margin: 0 !important;
}

.tft-footer__form {
  display: flex !important;
  position: relative !important;
  width: 100% !important;
}

.tft-footer__input {
  width: 100% !important;
  background-color: var(--fur-surface) !important;
  border: 1px solid var(--fur-border) !important;
  padding-block: 12px !important;
  padding-inline: 16px 48px !important;
  font-size: var(--fur-fs-small) !important;
  font-family: var(--fur-font-sans) !important;
  color: var(--fur-text) !important;
  border-radius: var(--fur-radius-sm) !important;
  transition: border-color var(--fur-transition-fast) !important;
}

.tft-footer__input:focus {
  outline: none !important;
  border-color: var(--fur-primary) !important;
}

.tft-footer__submit-btn {
  position: absolute !important;
  inset-block: 0 !important;
  inset-inline-end: 0 !important;
  width: 48px !important;
  background: transparent !important;
  border: none !important;
  color: var(--fur-text-muted) !important;
  cursor: pointer !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-size: 1.2rem !important;
  transition: color var(--fur-transition-fast) !important;
}

.tft-footer__submit-btn:hover {
  color: var(--fur-primary) !important;
}

.tft-footer__disclaimer {
  font-size: 0.75rem !important;
  color: var(--fur-text-muted) !important;
  line-height: 1.4 !important;
  margin: 0 !important;
}

/* Divider & Meta Bottom Row */
.tft-footer__divider {
  width: 100% !important;
  height: 1px !important;
  background-color: var(--fur-border) !important;
  margin-block-end: 24px !important;
}

.tft-footer__meta-row {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  gap: 20px !important;
  flex-wrap: wrap !important;
}

.tft-footer__copyright {
  font-size: 0.8rem !important;
  color: var(--fur-text-muted) !important;
  margin: 0 !important;
}

.tft-footer__meta-links {
  display: flex !important;
  gap: 20px !important;
  flex-wrap: wrap !important;
}

.tft-footer__meta-links a {
  font-size: 0.8rem !important;
  color: var(--fur-text-muted) !important;
  text-decoration: none !important;
  transition: color var(--fur-transition-fast) !important;
}

.tft-footer__meta-links a:hover {
  color: var(--fur-primary) !important;
}

.tft-footer__galleries {
  font-size: 0.8rem !important;
  color: var(--fur-text-muted) !important;
  letter-spacing: 0.05em !important;
}

