.tft-drawer__header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding-inline: clamp(20px, 5vw, 32px) !important;
  padding-block: 22px 20px !important;
  background: linear-gradient(135deg,
      var(--fur-ref-green-900) 0%,
      var(--fur-ref-green-700) 60%,
      var(--fur-ref-olive-500) 100%) !important;
  position: relative !important;
  flex-shrink: 0 !important;
  overflow: hidden !important;
}

/* Decorative circles */
.tft-drawer__header::before {
  content: "" !important;
  position: absolute !important;
  inset-block-end: -40px !important;
  inset-inline-end: -40px !important;
  width: 120px !important;
  height: 120px !important;
  border-radius: var(--fur-radius-full) !important;
  background: var(--fur-ref-lime-400) !important;
  opacity: 0.12 !important;
  pointer-events: none !important;
}

.tft-drawer__header::after {
  content: "" !important;
  position: absolute !important;
  inset-block-start: -20px !important;
  inset-inline-start: 60% !important;
  width: 70px !important;
  height: 70px !important;
  border-radius: var(--fur-radius-full) !important;
  background: var(--fur-ref-white) !important;
  opacity: 0.06 !important;
  pointer-events: none !important;
}

.tft-drawer__brand {
  display: flex !important;
  flex-direction: column !important;
  gap: 2px !important;
}

.tft-drawer__brand-mark {
  font-family: var(--fur-font-serif) !important;
  font-size: clamp(1.5rem, 4vw, 2rem) !important;
  font-weight: 700 !important;
  color: var(--fur-ref-white) !important;
  line-height: 1 !important;
  letter-spacing: -0.02em !important;
}

.tft-drawer__brand-tagline {
  font-family: var(--fur-font-sans) !important;
  font-size: 0.65rem !important;
  font-weight: 400 !important;
  color: var(--fur-ref-lime-400) !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
  opacity: 0.9 !important;
}

