.tft-nav-dropdown__btn,
.fur-sidebar__nav-link {
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  gap: 14px !important;
  width: 100% !important;
  padding-block: 13px !important;
  padding-inline: 14px !important;
  border-radius: var(--fur-radius-md) !important;
  font-family: var(--fur-font-sans) !important;
  font-size: 0.95rem !important;
  font-weight: 600 !important;
  color: var(--fur-text) !important;
  background: transparent !important;
  border: none !important;
  cursor: pointer !important;
  text-decoration: none !important;
  text-align: start !important;
  overflow: hidden !important;
  transition:
    background var(--fur-transition-fast),
    color var(--fur-transition-fast),
    transform var(--fur-transition-fast) !important;
}

.tft-nav-dropdown__btn:hover,
.fur-sidebar__nav-link:hover {
  background: var(--fur-sidebar-active) !important;
  color: var(--fur-primary) !important;
  transform: translateX(3px) !important;
}

.tft-nav-dropdown__btn:active,
.fur-sidebar__nav-link:active {
  transform: translateX(1px) scale(0.98) !important;
}

.tft-nav-dropdown__btn:hover .fur-icon,
.fur-sidebar__nav-link:hover .fur-icon {
  color: var(--fur-primary) !important;
  transform: scale(1.1) !important;
  transition: transform var(--fur-transition-fast), color var(--fur-transition-fast) !important;
}

