/* display is always flex; JS controls max-height inline for the transition */
.tft-nav-dropdown__menu {
  list-style: none !important;
  padding: 0 !important;
  margin: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 0 !important;
  overflow: hidden !important;
  max-height: 0;
  /* collapsed by default; JS sets exact value via inline style */
  transition: max-height 0.42s cubic-bezier(0.16, 1, 0.3, 1) !important;
  border-inline-start: 2px solid var(--fur-border) !important;
  margin-inline-start: 22px !important;
  padding-inline-start: 12px !important;
  margin-block: 0 4px !important;
}

.tft-nav-dropdown__btn[aria-expanded="true"]+.tft-nav-dropdown__menu {
  border-inline-start-color: var(--fur-primary) !important;
