.tft-nav-dropdown__link {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  font-family: var(--fur-font-sans) !important;
  font-size: 0.84rem !important;
  font-weight: 400 !important;
  color: var(--fur-text-muted) !important;
  text-decoration: none !important;
  padding-block: 9px !important;
  padding-inline: 10px !important;
  border-radius: var(--fur-radius-sm) !important;
  position: relative !important;
  overflow: hidden !important;
  transition:
    color var(--fur-transition-fast),
    background var(--fur-transition-fast),
    padding-inline-start 0.25s cubic-bezier(0.16, 1, 0.3, 1),
    transform var(--fur-transition-fast) !important;
}

.tft-nav-dropdown__link::before {
  content: "" !important;
  display: inline-block !important;
  width: 5px !important;
  height: 5px !important;
  border-radius: var(--fur-radius-full) !important;
  background: var(--fur-border-light) !important;
  flex-shrink: 0 !important;
  transition:
    background var(--fur-transition-fast),
    transform var(--fur-transition-fast) !important;
}

.tft-nav-dropdown__link:hover {
  color: var(--fur-primary) !important;
  background: var(--fur-sidebar-active) !important;
  padding-inline-start: 16px !important;
  transform: translateX(2px) !important;
}

.tft-nav-dropdown__link:hover::before {
  background: var(--fur-primary) !important;
  transform: scale(1.6) !important;
}

.tft-nav-dropdown__link:active {
