}

.tft-blog-filter-btn:hover {
  background: var(--fur-sidebar-active) !important;
  color: var(--fur-primary) !important;
  border-color: var(--fur-primary) !important;
}

.tft-blog-filter-btn--active {
  background: var(--fur-primary) !important;
  color: var(--fur-ref-white) !important;
