/* ================================================================
   SINGLE POST PAGE ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¯ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¿ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â½ blog-post.html
   ================================================================ */

/* Post Hero */
.tft-post-hero {
  position: relative;
  height: clamp(320px, 45vw, 520px);
  overflow: hidden;
  display: flex;
  align-items: flex-end;
}

.tft-post-hero__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scale(1.04);
  transition: transform 10s ease;
}

.tft-post-hero:hover .tft-post-hero__img {
  transform: scale(1);
}

.tft-post-hero__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, hsla(125, 34%, 8%, 0.88) 0%, hsla(125, 34%, 8%, 0.3) 55%, transparent 100%);
}

.tft-post-hero__content {
  position: relative;
  z-index: 2;
  padding-inline: clamp(24px, 6vw, 64px);
  padding-block-end: clamp(28px, 4vw, 52px);
  width: 100%;
}

.tft-post-hero__breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--fur-font-sans);
  font-size: .7rem;
  color: rgba(255, 255, 255, .6);
  margin-block-end: 12px;
  flex-wrap: wrap;
}

.tft-post-hero__breadcrumb a {
  color: rgba(255, 255, 255, .6);
  text-decoration: none;
  transition: color var(--fur-transition-fast);
}

.tft-post-hero__breadcrumb a:hover {
  color: var(--fur-ref-lime-400);
}

.tft-post-hero__tag {
  display: inline-block;
  font-family: var(--fur-font-sans);
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--fur-ref-lime-400);
  border: 1px solid rgba(255, 255, 255, .2);
  border-radius: var(--fur-radius-full);
  padding-inline: 14px;
  padding-block: 5px;
  backdrop-filter: blur(6px);
  margin-block-end: 14px;
}

.tft-post-hero__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.8rem, 4.5vw, 3.4rem);
  font-weight: 700;
  color: var(--fur-ref-white);
  line-height: 1.12;
  margin: 0 0 14px;
  max-width: 860px;
}

.tft-post-hero__meta {
  display: flex;
  align-items: center;
  gap: 16px;
  font-family: var(--fur-font-sans);
  font-size: .78rem;
  color: rgba(255, 255, 255, .65);
  flex-wrap: wrap;
}

.tft-post-hero__author-img {
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, .3);
}

/* Post Layout */
.tft-post-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: clamp(32px, 4vw, 56px);
  padding-inline: clamp(24px, 6vw, 64px);
  padding-block: clamp(32px, 4vw, 52px);
  align-items: start;
}

@media(max-width:1024px) {
  .tft-post-layout {
    grid-template-columns: 1fr;
  }
}

/* Progress bar */
.tft-post-progress {
  height: 3px;
  background: var(--fur-primary);
  width: 0%;
  position: sticky;
  inset-block-start: 0;
  z-index: 50;
  transition: width .1s linear;
}

/* Article Content */
.tft-post-article {
  min-width: 0;
}

.tft-post-article__lede {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  font-weight: 400;
  font-style: italic;
  color: var(--fur-text);
  line-height: 1.7;
  margin-block-end: 32px;
  padding-block-end: 28px;
  border-block-end: 1px solid var(--fur-border);
}

.tft-post-article__body {
  font-family: var(--fur-font-sans);
  font-size: clamp(.9rem, 1.1vw, 1.02rem);
  color: var(--fur-text);
  line-height: 1.8;
}

.tft-post-article__body h2 {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.3rem, 2.2vw, 1.8rem);
  font-weight: 700;
  color: var(--fur-text);
  margin-block: 36px 14px;
}

.tft-post-article__body h3 {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.1rem, 1.6vw, 1.4rem);
  font-weight: 600;
  margin-block: 28px 10px;
}

.tft-post-article__body p {
  margin-block-end: 22px;
}

.tft-post-article__body strong {
  font-weight: 700;
  color: var(--fur-text);
}

.tft-post-article__blockquote {
  border-inline-start: 4px solid var(--fur-primary);
  padding-inline: 28px;
  padding-block: 18px;
  background: var(--fur-sidebar-active);
  border-radius: 0 var(--fur-radius-md) var(--fur-radius-md) 0;
  margin-block: 32px;
}

.tft-post-article__blockquote p {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.05rem, 1.4vw, 1.22rem);
  font-style: italic;
  line-height: 1.65;
  margin: 0 0 8px;
}

.tft-post-article__blockquote cite {
  font-family: var(--fur-font-sans);
  font-size: .75rem;
  color: var(--fur-text-muted);
  font-style: normal;
  font-weight: 600;
  letter-spacing: .06em;
}

.tft-post-article__img-caption {
  width: 100%;
  border-radius: var(--fur-radius-md);
  margin-block: 28px;
  overflow: hidden;
}

.tft-post-article__img-caption img {
  width: 100%;
  display: block;
}

.tft-post-article__img-caption figcaption {
  font-family: var(--fur-font-sans);
  font-size: .72rem;
  color: var(--fur-text-muted);
  padding: 10px 14px;
  background: var(--fur-bg-secondary);
}

.tft-post-article__tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-block-start: 36px;
  padding-block-start: 24px;
  border-block-start: 1px solid var(--fur-border);
}

.tft-post-article__tag {
  font-family: var(--fur-font-sans);
  font-size: .72rem;
  font-weight: 600;
  color: var(--fur-text-muted);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-full);
  padding-inline: 14px;
  padding-block: 6px;
  text-decoration: none;
  transition: all var(--fur-transition-fast);
}

.tft-post-article__tag:hover {
  background: var(--fur-primary);
  color: var(--fur-ref-white);
  border-color: var(--fur-primary);
}

/* Author Box */
.tft-author-box {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 24px;
  align-items: start;
  background: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-xl);
  padding: clamp(20px, 3vw, 36px);
  margin-block-start: 48px;
  position: relative;
  overflow: hidden;
}

.tft-author-box::before {
  content: ;
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 0;
  width: 100%;
  height: 4px;
  background: linear-gradient(90deg, var(--fur-ref-green-900), var(--fur-ref-lime-400));
}

.tft-author-box__img {
  width: clamp(72px, 8vw, 96px);
  height: clamp(72px, 8vw, 96px);
  border-radius: var(--fur-radius-full);
  object-fit: cover;
  border: 3px solid var(--fur-border);
}

.tft-author-box__label {
  font-family: var(--fur-font-sans);
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--fur-primary);
  margin-block-end: 4px;
}

.tft-author-box__name {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.1rem, 1.6vw, 1.3rem);
  font-weight: 700;
  color: var(--fur-text);
  margin: 0 0 8px;
}

.tft-author-box__bio {
  font-family: var(--fur-font-sans);
  font-size: .88rem;
  color: var(--fur-text-muted);
  line-height: 1.65;
  margin: 0 0 14px;
}

.tft-author-box__links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.tft-author-box__link {
  font-family: var(--fur-font-sans);
  font-size: .72rem;
  font-weight: 700;
  color: var(--fur-primary);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: gap var(--fur-transition-fast);
}

.tft-author-box__link:hover {
  gap: 9px;
}

/* Comments Section */
.tft-comments {
  margin-block-start: 48px;
}

.tft-comments__heading {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.3rem, 2vw, 1.6rem);
  font-weight: 700;
  color: var(--fur-text);
  margin-block-end: 28px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.tft-comments__count {
  font-family: var(--fur-font-sans);
  font-size: .78rem;
  font-weight: 700;
  color: var(--fur-ref-white);
  background: var(--fur-primary);
  border-radius: var(--fur-radius-full);
  padding-inline: 10px;
  padding-block: 3px;
}

/* Comment Thread */
.tft-comment-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.tft-comment {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 14px;
  padding-block: 22px;
  border-block-end: 1px solid var(--fur-border);
  position: relative;
}

.tft-comment--child {
  padding-inline-start: 48px;
  background: linear-gradient(to right, var(--fur-border) 1px, transparent 1px);
  background-position: inset-inline-start 22px;
}

.tft-comment__avatar {
  width: 44px;
  height: 44px;
  border-radius: var(--fur-radius-full);
  object-fit: cover;
  flex-shrink: 0;
}

.tft-comment__avatar--placeholder {
  width: 44px;
  height: 44px;
  border-radius: var(--fur-radius-full);
  background: var(--fur-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--fur-font-serif);
  font-weight: 700;
  color: var(--fur-ref-white);
  font-size: 1rem;
  flex-shrink: 0;
}

.tft-comment__body {
  min-width: 0;
}

.tft-comment__header {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-block-end: 8px;
}

.tft-comment__author {
  font-family: var(--fur-font-sans);
  font-size: .88rem;
  font-weight: 700;
  color: var(--fur-text);
}

.tft-comment__badge {
  font-family: var(--fur-font-sans);
  font-size: .6rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--fur-ref-white);
  background: var(--fur-primary);
  border-radius: var(--fur-radius-full);
  padding-inline: 8px;
  padding-block: 2px;
}

.tft-comment__date {
  font-family: var(--fur-font-sans);
  font-size: .7rem;
  color: var(--fur-text-muted);
  margin-inline-start: auto;
}

.tft-comment__text {
  font-family: var(--fur-font-sans);
  font-size: .88rem;
  color: var(--fur-text);
  line-height: 1.7;
  margin-block-end: 10px;
}

.tft-comment__actions {
  display: flex;
  gap: 16px;
}

.tft-comment__action {
  font-family: var(--fur-font-sans);
  font-size: .72rem;
  font-weight: 600;
  color: var(--fur-text-muted);
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  transition: color var(--fur-transition-fast);
  display: flex;
  align-items: center;
  gap: 5px;
}

.tft-comment__action:hover {
  color: var(--fur-primary);
}

.tft-comment__action--liked {
  color: var(--fur-primary);
}

/* Comment Form */
.tft-comment-form {
  margin-block-start: 40px;
  background: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-xl);
  padding: clamp(22px, 3vw, 38px);
  position: relative;
  overflow: hidden;
}

.tft-comment-form::before {
  content: ;
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 0;
  width: 60px;
  height: 60px;
  border-radius: 0 0 var(--fur-radius-full) 0;
  background: var(--fur-sidebar-active);
  pointer-events: none;
}

.tft-comment-form__heading {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.1rem, 1.6vw, 1.35rem);
  font-weight: 700;
  color: var(--fur-text);
  margin-block-end: 20px;
}

.tft-comment-form__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-block-end: 14px;
}

@media(max-width:560px) {
  .tft-comment-form__grid {
    grid-template-columns: 1fr;
  }
}

.tft-comment-form__field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tft-comment-form__field--full {
  grid-column: 1/-1;
}

.tft-comment-form__label {
  font-family: var(--fur-font-sans);
  font-size: .72rem;
  font-weight: 700;
  color: var(--fur-text-muted);
  letter-spacing: .04em;
}

.tft-comment-form__input,
.tft-comment-form__textarea {
  font-family: var(--fur-font-sans);
  font-size: .88rem;
  color: var(--fur-text);
  background: var(--fur-bg);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  padding-inline: 16px;
  padding-block: 12px;
  outline: none;
  transition: border-color var(--fur-transition-fast), box-shadow var(--fur-transition-fast);
  width: 100%;
  box-sizing: border-box;
}

.tft-comment-form__input:focus,
.tft-comment-form__textarea:focus {
  border-color: var(--fur-primary);
  box-shadow: 0 0 0 3px var(--fur-sidebar-active);
}

.tft-comment-form__textarea {
  resize: vertical;
  min-height: 130px;
  line-height: 1.65;
}

.tft-comment-form__submit {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--fur-font-sans);
  font-size: .85rem;
  font-weight: 700;
  color: var(--fur-ref-white);
  background: var(--fur-primary);
  border: none;
  border-radius: var(--fur-radius-full);
  padding-inline: 28px;
  padding-block: 13px;
  cursor: pointer;
  margin-block-start: 8px;
  transition: background var(--fur-transition-fast), transform var(--fur-transition-fast);
}

.tft-comment-form__submit:hover {
  background: var(--fur-primary-hover);
  transform: translateY(-1px);
}

/* Sidebar Widgets */
.tft-post-sidebar {
  display: flex;
  flex-direction: column;
  gap: 24px;
  position: sticky;
  inset-block-start: 80px;
}

.tft-widget {
  background: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-xl);
  overflow: hidden;
}

.tft-widget__header {
  padding: 18px 22px 14px;
  border-block-end: 1px solid var(--fur-border);
  display: flex;
  align-items: center;
  gap: 10px;
}

.tft-widget__icon {
  width: 32px;
  height: 32px;
  border-radius: var(--fur-radius-md);
  background: var(--fur-sidebar-active);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fur-primary);
  flex-shrink: 0;
}

.tft-widget__title {
  font-family: var(--fur-font-serif);
  font-size: .98rem;
  font-weight: 700;
  color: var(--fur-text);
  margin: 0;
}

.tft-widget__body {
  padding: 18px 22px;
}

/* Widget: Author */
.tft-widget-author {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 10px;
}

.tft-widget-author__img {
  width: 72px;
  height: 72px;
  border-radius: var(--fur-radius-full);
  object-fit: cover;
  border: 3px solid var(--fur-border);
}

.tft-widget-author__name {
  font-family: var(--fur-font-serif);
  font-size: 1rem;
  font-weight: 700;
  color: var(--fur-text);
}

.tft-widget-author__role {
  font-family: var(--fur-font-sans);
  font-size: .72rem;
  color: var(--fur-primary);
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.tft-widget-author__bio {
  font-family: var(--fur-font-sans);
  font-size: .8rem;
  color: var(--fur-text-muted);
  line-height: 1.65;
}

.tft-widget-author__btn {
  font-family: var(--fur-font-sans);
  font-size: .75rem;
  font-weight: 700;
  color: var(--fur-primary);
  border: 1px solid var(--fur-primary);
  border-radius: var(--fur-radius-full);
  padding-inline: 18px;
  padding-block: 7px;
  text-decoration: none;
  transition: all var(--fur-transition-fast);
}

.tft-widget-author__btn:hover {
  background: var(--fur-primary);
  color: var(--fur-ref-white);
}

/* Widget: Related Posts */
.tft-widget-related {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.tft-widget-related__item {
  display: grid;
  grid-template-columns: 72px 1fr;
  gap: 12px;
  align-items: center;
  text-decoration: none;
  transition: transform var(--fur-transition-fast);
}

.tft-widget-related__item:hover {
  transform: translateX(3px);
}

.tft-widget-related__img {
  width: 72px;
  height: 56px;
  border-radius: var(--fur-radius-sm);
  object-fit: cover;
}

.tft-widget-related__title {
  font-family: var(--fur-font-serif);
  font-size: .84rem;
  font-weight: 600;
  color: var(--fur-text);
  line-height: 1.35;
  transition: color var(--fur-transition-fast);
}

.tft-widget-related__item:hover .tft-widget-related__title {
  color: var(--fur-primary);
}

.tft-widget-related__date {
  font-family: var(--fur-font-sans);
  font-size: .65rem;
  color: var(--fur-text-muted);
  margin-block-start: 3px;
}

/* Widget: Categories */
.tft-widget-cats {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tft-widget-cats__item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--fur-font-sans);
  font-size: .84rem;
  color: var(--fur-text);
  text-decoration: none;
  padding-block: 9px;
  padding-inline: 10px;
  border-radius: var(--fur-radius-sm);
  transition: all var(--fur-transition-fast);
}

.tft-widget-cats__item:hover {
  background: var(--fur-sidebar-active);
  color: var(--fur-primary);
}

.tft-widget-cats__count {
  font-size: .7rem;
  font-weight: 700;
  color: var(--fur-ref-white);
  background: var(--fur-primary);
  border-radius: var(--fur-radius-full);
  padding-inline: 8px;
  padding-block: 2px;
}

/* Widget: Tags */
.tft-widget-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.tft-widget-tag {
  font-family: var(--fur-font-sans);
  font-size: .7rem;
  font-weight: 600;
  color: var(--fur-text-muted);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-full);
  padding-inline: 12px;
  padding-block: 5px;
  text-decoration: none;
  transition: all var(--fur-transition-fast);
}

.tft-widget-tag:hover {
  background: var(--fur-primary);
  color: var(--fur-ref-white);
  border-color: var(--fur-primary);
}

/* Widget: Newsletter */
.tft-widget-newsletter {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.tft-widget-newsletter__desc {
  font-family: var(--fur-font-sans);
  font-size: .8rem;
  color: var(--fur-text-muted);
  line-height: 1.6;
}

.tft-widget-newsletter__input {
  font-family: var(--fur-font-sans);
  font-size: .82rem;
  color: var(--fur-text);
  background: var(--fur-bg);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  padding: 11px 14px;
  outline: none;
  box-sizing: border-box;
  width: 100%;
  transition: border-color var(--fur-transition-fast);
}

.tft-widget-newsletter__input:focus {
  border-color: var(--fur-primary);
}

.tft-widget-newsletter__btn {
  font-family: var(--fur-font-sans);
  font-size: .8rem;
  font-weight: 700;
  color: var(--fur-ref-white);
  background: var(--fur-primary);
  border: none;
  border-radius: var(--fur-radius-md);
  padding-block: 11px;
  cursor: pointer;
  transition: background var(--fur-transition-fast);
}

.tft-widget-newsletter__btn:hover {
  background: var(--fur-primary-hover);
}

/* Widget: Featured Product */
.tft-widget-product {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tft-widget-product__img {
  width: 100%;
  border-radius: var(--fur-radius-md);
  object-fit: cover;
  display: block;
  aspect-ratio: 4/3;
}

.tft-widget-product__name {
  font-family: var(--fur-font-serif);
  font-size: .95rem;
  font-weight: 700;
  color: var(--fur-text);
}

.tft-widget-product__desc {
  font-family: var(--fur-font-sans);
  font-size: .78rem;
  color: var(--fur-text-muted);
  line-height: 1.55;
}

.tft-widget-product__price {
  font-family: var(--fur-font-sans);
  font-size: 1rem;
  font-weight: 700;
  color: var(--fur-primary);
}

.tft-widget-product__btn {
  display: block;
  font-family: var(--fur-font-sans);
  font-size: .78rem;
  font-weight: 700;
  color: var(--fur-ref-white);
  background: var(--fur-primary);
  border-radius: var(--fur-radius-full);
  padding-block: 10px;
  text-align: center;
  text-decoration: none;
  transition: background var(--fur-transition-fast);
}

.tft-widget-product__btn:hover {
  background: var(--fur-primary-hover);
}

/* Dark mode */
body[data-theme='dark'] .tft-comment-form__input,
body[data-theme='dark'] .tft-comment-form__textarea,
body[data-theme='dark'] .tft-widget-newsletter__input {
  background: var(--fur-ref-forest-800) !important;
}



/* ==========================================================================
   TFT PREMIUM FOOTER REBUILD (HIGH FIDELITY)
   ========================================================================== */

.tft-footer {
  display: flex;
  flex-direction: column;
  background-color: transparent !important;
  border: none !important;
  padding: 0 !important;
  margin-block-start: var(--fur-margin-block-lg);
  box-shadow: none !important;
}

.tft-footer__upper {
  background-color: var(--fur-ref-beige-50);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-xl);
  margin-inline: clamp(12px, 2.5vw, 24px);
  padding-inline: clamp(20px, 4vw, 60px);
  padding-block: clamp(40px, 6vw, 80px) clamp(30px, 4vw, 40px);
}

.tft-footer__main-grid {
  display: grid;
  grid-template-columns: 2.2fr 1fr 1fr 1fr 1.8fr 1.5fr;
  gap: clamp(20px, 2.5vw, 40px);
  align-items: start;
}

.tft-footer__col-brand {
  display: flex;
  flex-direction: column;
  align-items: start;
}

.tft-footer__logo {
  font-family: var(--fur-font-serif);
  font-size: 2.2rem;
  font-weight: 700;
  text-decoration: none;
  color: var(--fur-text);
  margin-block-end: 16px;
  display: inline-block;
  line-height: 1;
}

.tft-footer__tagline {
  font-family: var(--fur-font-sans);
  font-size: 0.88rem;
  line-height: 1.6;
  color: var(--fur-text-muted);
  margin-block-end: 24px;
  max-width: 320px;
}

.tft-footer__contact-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-block-end: 24px;
  width: 100%;
}

.tft-footer__contact-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.tft-footer__contact-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-ref-beige-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fur-primary);
  flex-shrink: 0;
}

.tft-footer__contact-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tft-footer__contact-info strong {
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--fur-text);
}

.tft-footer__contact-info span {
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  color: var(--fur-text-muted);
}

.tft-footer__social-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 100%;
}

.tft-footer__social-title {
  font-family: var(--fur-font-sans);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--fur-text);
}

.tft-footer__social-links {
  display: flex;
  gap: 10px;
}

.tft-footer__social-btn {
  width: 36px;
  height: 36px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-ref-beige-100);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fur-text);
  text-decoration: none;
  transition: all var(--fur-transition-fast);
}

.tft-footer__social-btn:hover {
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  transform: translateY(-2px);
}

.tft-footer__col-links {
  display: flex;
  flex-direction: column;
}

.tft-footer__heading {
  font-family: var(--fur-font-sans);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--fur-text);
  position: relative;
  margin-block-end: 24px;
  padding-block-end: 8px;
}

.tft-footer__heading::after {
  content: '';
  position: absolute;
  inset-block-start: 100%;
  inset-inline-start: 0;
  width: 4px;
  height: 4px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-accent);
}

.tft-footer__links-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 0;
  margin: 0;
}

.tft-footer__links-list a {
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  color: var(--fur-text-muted);
  text-decoration: none;
  transition: color var(--fur-transition-fast), padding-inline-start var(--fur-transition-fast);
}

.tft-footer__links-list a:hover {
  color: var(--fur-primary);
  padding-inline-start: 4px;
}

.tft-footer__col-newsletter {
  display: flex;
  flex-direction: column;
}

.tft-footer__newsletter-text {
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  line-height: 1.6;
  color: var(--fur-text-muted);
  margin-block-end: 18px;
}

.tft-footer__form {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  margin-block-end: 16px;
}

.tft-footer__input {
  width: 100%;
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  color: var(--fur-text);
  padding-block: 12px;
  padding-inline-start: 16px;
  padding-inline-end: 50px;
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-ref-beige-50);
  outline: none;
  transition: border-color var(--fur-transition-fast);
}

.tft-footer__input:focus {
  border-color: var(--fur-primary);
  background-color: var(--fur-ref-white);
}

.tft-footer__submit-btn {
  position: absolute;
  inset-inline-end: 6px;
  width: 32px;
  height: 32px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-primary);
  border: none;
  color: var(--fur-ref-white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color var(--fur-transition-fast);
}

.tft-footer__submit-btn:hover {
  background-color: var(--fur-primary-hover);
}

.tft-footer__checkbox-wrapper {
  display: flex;
  align-items: start;
  gap: 8px;
}

.tft-footer__checkbox-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border-radius: 4px;
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  flex-shrink: 0;
  margin-block-start: 2px;
}

.tft-footer__checkbox-label {
  font-family: var(--fur-font-sans);
  font-size: 0.76rem;
  line-height: 1.4;
  color: var(--fur-text-muted);
}

.tft-footer__col-arch {
  display: flex;
  justify-content: flex-end;
  align-items: start;
}

.tft-footer__arch-frame {
  border-radius: 120px 120px 0px 0px;
  overflow: hidden;
  width: 100%;
  max-width: 220px;
  aspect-ratio: 2.2 / 3;
  border: 1px solid var(--fur-border);
}

.tft-footer__arch-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.tft-footer__trust-strip {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  background-color: var(--fur-ref-beige-100);
  border-radius: var(--fur-radius-md);
  padding: 20px 32px;
  margin-block-start: 48px;
  border: 1px solid var(--fur-border);
}

.tft-footer__trust-card {
  display: flex;
  align-items: center;
  gap: 16px;
  flex: 1;
}

.tft-footer__trust-icon {
  width: 42px;
  height: 42px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-ref-white);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fur-primary);
  border: 1px solid var(--fur-border);
  flex-shrink: 0;
}

.tft-footer__trust-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tft-footer__trust-content strong {
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--fur-text);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.tft-footer__trust-content span {
  font-family: var(--fur-font-sans);
  font-size: 0.74rem;
  color: var(--fur-text-muted);
}

.tft-footer__lower {
  background-color: var(--fur-ref-green-900);
  border-radius: var(--fur-radius-lg) var(--fur-radius-lg) 0 0;
  margin-inline: clamp(12px, 2.5vw, 24px);
  margin-block-start: -16px;
  padding-inline: clamp(20px, 4vw, 60px);
  padding-block: 40px;
  color: var(--fur-ref-beige-50);
  z-index: 2;
  position: relative;
}

.tft-footer__lower-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 40px;
}

.tft-footer__quote-block {
  display: flex;
  align-items: center;
  gap: 16px;
  max-width: 380px;
}

.tft-footer__quote-thumb {
  width: 64px;
  height: 64px;
  border-radius: var(--fur-radius-sm);
  object-fit: cover;
  flex-shrink: 0;
}

.tft-footer__quote-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tft-footer__quote-symbol {
  font-family: var(--fur-font-serif);
  font-size: 2.5rem;
  color: var(--fur-ref-lime-400);
  line-height: 1;
  height: 16px;
  display: block;
  margin-block-start: -12px;
}

.tft-footer__quote-text {
  font-family: var(--fur-font-serif);
  font-size: 0.95rem;
  font-style: italic;
  color: var(--fur-ref-beige-50);
  line-height: 1.4;
}

.tft-footer__quote-author {
  font-family: var(--fur-font-sans);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--fur-ref-lime-400);
  text-transform: uppercase;
}

.tft-footer__seen-in {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.tft-footer__seen-label {
  font-family: var(--fur-font-sans);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--fur-ref-beige-dark-muted);
  text-transform: uppercase;
}

.tft-footer__seen-logos {
  display: flex;
  align-items: center;
  gap: clamp(16px, 2.5vw, 32px);
}

.tft-footer__seen-logo-item {
  color: var(--fur-ref-beige-50);
  opacity: 0.85;
  white-space: nowrap;
}

.tft-footer__meta-info {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
  text-align: right;
}

.tft-footer__meta-galleries {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tft-footer__globe-icon {
  width: 32px;
  height: 32px;
  border-radius: var(--fur-radius-full);
  border: 1px solid var(--fur-ref-beige-dark-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fur-ref-lime-400);
  background: transparent;
  flex-shrink: 0;
}

.tft-footer__gallery-cities {
  font-family: var(--fur-font-sans);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--fur-ref-beige-50);
}

.tft-footer__copyright-text {
  font-family: var(--fur-font-sans);
  font-size: 0.75rem;
  color: var(--fur-ref-beige-dark-muted);
}

/* ------------------------------------------------------------------------
   RESPONSIVE DESIGN (FLUID BREAKPOINTS)
   ------------------------------------------------------------------------ */

@media (max-width: 1200px) {
  .tft-footer__main-grid {
    grid-template-columns: 2fr 1fr 1fr 1.5fr 1.2fr;
  }

  .tft-footer__col-arch {
    display: none;
  }
}

@media (max-width: 991px) {
  .tft-footer__main-grid {
    grid-template-columns: 1.5fr 1fr 1fr 1.5fr;
  }

  .tft-footer__trust-strip {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    padding: 24px;
  }

  .tft-footer__lower-container {
    flex-direction: column;
    align-items: flex-start;
    gap: 32px;
  }

  .tft-footer__meta-info {
    align-items: flex-start;
    text-align: left;
    width: 100%;
  }

  .tft-footer__seen-in {
    align-items: flex-start;
    width: 100%;
  }
}

@media (max-width: 768px) {
  .tft-footer__main-grid {
    grid-template-columns: 1fr 1fr;
    gap: 30px;
  }

  .tft-footer__col-brand {
    grid-column: span 2;
    margin-block-end: 20px;
  }

  .tft-footer__col-newsletter {
    grid-column: span 2;
    margin-block-start: 20px;
  }
}

@media (max-width: 480px) {
  .tft-footer__main-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .tft-footer__col-brand,
  .tft-footer__col-newsletter {
    grid-column: span 1;
  }

  .tft-footer__trust-strip {
    grid-template-columns: 1fr;
    gap: 16px;
    padding: 20px;
  }

  .tft-footer__seen-logos {
    flex-wrap: wrap;
    gap: 16px;
  }

  .tft-footer__gallery-cities {
    font-size: 0.65rem;
  }
}

/* Dark Mode Overrides */
body[data-theme='dark'] .tft-footer__upper {
  background-color: var(--fur-ref-forest-800);
  border-color: var(--fur-ref-forest-700);
}

body[data-theme='dark'] .tft-footer__contact-icon,
body[data-theme='dark'] .tft-footer__social-btn {
  background-color: var(--fur-ref-forest-700);
  color: var(--fur-ref-beige-dark);
}

body[data-theme='dark'] .tft-footer__trust-strip {
  background-color: var(--fur-ref-forest-900);
  border-color: var(--fur-ref-forest-700);
}

body[data-theme='dark'] .tft-footer__trust-icon {
  background-color: var(--fur-ref-forest-800);
  border-color: var(--fur-ref-forest-700);
}

body[data-theme='dark'] .tft-footer__input {
  background-color: var(--fur-ref-forest-700);
  border-color: var(--fur-ref-forest-600);
  color: var(--fur-ref-beige-50);
}

body[data-theme='dark'] .tft-footer__input:focus {
  border-color: var(--fur-ref-lime-400);
}

/* ==========================================================================
   TFT REDESIGNED TESTIMONIALS & FEATURES BAR (ThemeForest/WP Ready)
   ========================================================================== */

.tft-testimonials {
  padding-block: clamp(60px, 8vw, 120px);
  padding-inline: clamp(24px, 5vw, 80px);
  background-color: var(--fur-bg-secondary);
  color: var(--fur-text);
  position: relative;
  overflow: hidden;
}

body[data-theme="dark"] .tft-testimonials {
  background-color: var(--fur-ref-forest-900);
  color: var(--fur-ref-beige-100);
}

.tft-testimonials__container {
  max-width: 1400px;
  margin-inline: auto;
}

.tft-testimonials__header {
  text-align: center;
  margin-block-end: clamp(40px, 6vw, 80px);
  max-width: 600px;
  margin-inline: auto;
}

.tft-testimonials__eyebrow {
  display: block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--fur-primary);
  margin-block-end: 12px;
}

body[data-theme="dark"] .tft-testimonials__eyebrow {
  color: var(--fur-ref-lime-400);
}

.tft-testimonials__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(2rem, 3.5vw, 3rem);
  font-weight: 400;
  line-height: 1.15;
  margin: 0 0 16px 0;
  color: inherit;
}

.tft-testimonials__title em {
  font-style: italic;
  font-weight: 400;
}

.tft-testimonials__subtitle {
  font-size: clamp(0.95rem, 1.2vw, 1.1rem);
  color: var(--fur-text-muted);
  line-height: 1.6;
  margin: 0;
}

body[data-theme="dark"] .tft-testimonials__subtitle {
  color: var(--fur-ref-lime-400);
}

/* Grid Layout */
.tft-testimonials__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-block-end: clamp(50px, 7vw, 100px);
}

@media (max-width: 1200px) {
  .tft-testimonials__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 680px) {
  .tft-testimonials__grid {
    grid-template-columns: 1fr;
  }
}

/* Card Styling */
.tft-testimonial-card {
  background-color: var(--fur-surface);
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100%;
  transition: transform var(--fur-transition-normal), box-shadow var(--fur-transition-normal);
}

body[data-theme="dark"] .tft-testimonial-card {
  background-color: var(--fur-ref-forest-800);
}

.tft-testimonial-card:hover {
  transform: translateY(-6px);
}

/* Top Image of Card */
.tft-testimonial-card__img-wrap {
  position: relative;
  aspect-ratio: 3 / 2;
  overflow: hidden;
}

.tft-testimonial-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--fur-transition-slow);
}

.tft-testimonial-card:hover .tft-testimonial-card__img {
  transform: scale(1.04);
}

/* Overlapping Quote Badge */
.tft-testimonial-card__quote-badge {
  position: absolute;
  inset-block-end: -20px;
  inset-inline-end: 24px;
  width: 40px;
  height: 40px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

body[data-theme="dark"] .tft-testimonial-card__quote-badge {
  background-color: var(--fur-ref-lime-400);
  color: var(--fur-ref-forest-900);
}

.tft-testimonial-card__quote-badge svg {
  width: 16px;
  height: 16px;
}

/* Card Body */
.tft-testimonial-card__body {
  padding: 32px 24px 24px 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

/* Rating Stars (Green) */
.tft-testimonial-card__rating {
  display: flex;
  gap: 2px;
  margin-block-end: 16px;
  color: var(--fur-primary);
  font-size: 0.9rem;
}

body[data-theme="dark"] .tft-testimonial-card__rating {
  color: var(--fur-ref-lime-400);
}

/* Quote Text */
.tft-testimonial-card__quote {
  font-family: var(--fur-font-serif);
  font-style: italic;
  font-size: clamp(0.95rem, 1.1vw, 1.05rem);
  line-height: 1.6;
  color: inherit;
  margin: 0 0 24px 0;
  flex-grow: 1;
}

/* Author Footer */
.tft-testimonial-card__footer {
  display: flex;
  align-items: center;
  gap: 12px;
  border-block-start: 1px solid var(--fur-border);
  padding-block-start: 16px;
}

body[data-theme="dark"] .tft-testimonial-card__footer {
  border-color: var(--fur-ref-forest-700);
}

.tft-testimonial-card__avatar {
  width: 40px;
  height: 40px;
  border-radius: var(--fur-radius-full);
  object-fit: cover;
}

.tft-testimonial-card__meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tft-testimonial-card__author {
  font-size: 0.85rem;
  font-weight: 700;
  color: inherit;
}

.tft-testimonial-card__location {
  font-size: 0.72rem;
  color: var(--fur-text-muted);
}

body[data-theme="dark"] .tft-testimonial-card__location {
  color: var(--fur-ref-beige-dark-muted);
}

/* Horizontal Features Bar */
.tft-features-bar {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(16px, 3vw, 40px);
  padding-block-start: clamp(40px, 6vw, 80px);
  border-block-start: 1px solid var(--fur-border);
  text-align: center;
}

body[data-theme="dark"] .tft-features-bar {
  border-color: var(--fur-ref-forest-700);
}

.tft-features-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.tft-features-bar__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-bg);
  color: var(--fur-primary);
}

body[data-theme="dark"] .tft-features-bar__icon {
  background-color: var(--fur-ref-forest-700);
  color: var(--fur-ref-lime-400);
}

.tft-features-bar__text {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: inherit;
}

@media (max-width: 820px) {
  .tft-features-bar {
    grid-template-columns: repeat(2, 1fr);
    gap: 24px;
  }
}

@media (max-width: 480px) {
  .tft-features-bar {
    grid-template-columns: 1fr;
    gap: 20px;
  }
}

