.tft-blog-hero,
.tft-post-hero,
.fur-hero,
.fur-hero-slider {
  border-top-left-radius: var(--fur-radius-xl) !important;
  border-top-right-radius: var(--fur-radius-xl) !important;
  overflow: hidden !important;
}

