  font-weight: 700 !important;
  width: 15px !important;
  height: 15px !important;
  border-radius: var(--fur-radius-full) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  border: 1.5px solid var(--fur-sidebar-bg) !important;
}

/* Mobile Nav Drawer overlay inside sidebar */
.tft-redesign-layout .tft-mobile-drawer {
  display: none !important;
}

/* 3. Main content viewport */
.tft-redesign-layout .fur-main {
  width: calc(100vw - 100px) !important;
  flex-grow: 1 !important;
  height: 100vh !important;
  overflow-y: auto !important;
  background-color: var(--fur-bg-secondary) !important;
  padding-inline: clamp(24px, 4vw, 64px) !important;
  padding-block: clamp(24px, 4vw, 48px) !important;
  transition: background-color var(--fur-transition-normal) !important;
}

/* 4. Top Bar layout styles */
.tft-redesign-layout .tft-top-bar {
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
  gap: 24px !important;
  margin-block-end: 24px !important;
}

.tft-redesign-layout .tft-top-bar__search {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  background-color: var(--fur-surface) !important;
  border: 1px solid var(--fur-border) !important;
  border-radius: var(--fur-radius-full) !important;
  padding-inline: 24px !important;
  height: 48px !important;
  width: 100% !important;
  max-width: 540px !important;
