/* ==========================================================================
   9. RESPONSIVE MEDIA QUERIES FOR REDESIGN (MOBILE & TABLET)
   ========================================================================== */
@media (max-width: 1024px) {
  .tft-redesign-layout .fur-app-layout {
    flex-direction: column !important;
    height: auto !important;
    overflow-y: visible !important;
