/* Fullscreen Viewport and resets */
body,
html {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: var(--fur-font-sans);
  background-color: var(--fur-bg);
  color: var(--fur-text);
  transition: background-color var(--fur-transition-normal) ease, color var(--fur-transition-normal) ease;
}

/* 3D Spatial Canvas Container */
.tft-fnd-viewport {
  position: fixed;
  inset: 0;
  overflow: hidden;
  perspective: 1200px;
  perspective-origin: 50% 50%;
  z-index: 2;
  cursor: grab;
}

.tft-fnd-viewport:active {
  cursor: grabbing;
}

/* 3D Spatial Scene Pivot Node */
.tft-fnd-scene {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  transform-style: preserve-3d;
  will-change: transform;
}

/* Spatial Product Card Grid Item */
.tft-fnd-card {
  position: absolute;
  width: 300px;
  height: 400px;
  left: -150px;
  top: -200px;
  transform-style: preserve-3d;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  box-shadow: 0 10px 40px var(--fur-shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 28px;
  box-sizing: border-box;
  /* NO transform transition here - transform is smoothed programmatically in JS to prevent initial snapping jitter! */
  transition: opacity 0.4s ease, background-color var(--fur-transition-normal) ease, border-color var(--fur-transition-normal) ease, box-shadow 0.4s ease;
  will-change: transform, opacity;
}

.tft-fnd-card:hover {
  box-shadow: 0 20px 50px var(--fur-shadow-lg);
  border-color: var(--fur-primary);
}

