  font-weight: 600;
  box-shadow: 0 10px 30px var(--fur-shadow-lg);
  z-index: 50;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

.tft-fnd-toast--visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* Scrollbar styling for drawer */
.tft-fnd-drawer__body::-webkit-scrollbar {
  width: 4px;
}

.tft-fnd-drawer__body::-webkit-scrollbar-track {
  background: transparent;
}

.tft-fnd-drawer__body::-webkit-scrollbar-thumb {
  background: var(--fur-border-light);
  border-radius: var(--fur-radius-full);
}

/* 3D Typography Parallax Watermark Backdrop */
.tft-fnd-scene__backdrop {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate3d(-50%, -50%, -600px);
  transform-style: preserve-3d;
  text-align: center;
  pointer-events: none;
  white-space: nowrap;
  user-select: none;
  opacity: 0.06;
  transition: opacity var(--fur-transition-normal) ease;
}

body[data-theme="dark"] .tft-fnd-scene__backdrop {
  opacity: 0.035;
}

.tft-fnd-scene__backdrop-main {
  font-family: var(--fur-font-serif);
  font-size: clamp(8rem, 24vw, 22rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.15em;
  color: var(--fur-text);
  text-transform: uppercase;
}

.tft-fnd-scene__backdrop-sub {
  font-family: var(--fur-font-sans);
  font-size: clamp(0.7rem, 2vw, 1.1rem);
  font-weight: 600;
  letter-spacing: 0.35em;
  color: var(--fur-text);
  margin-top: 20px;
  text-transform: uppercase;
}

/* Spatial Section Placards */
.tft-fnd-placard {
  position: absolute;
  left: 0;
  top: 0;
  transform-style: preserve-3d;
  pointer-events: none;
  white-space: nowrap;
  user-select: none;
}

.tft-fnd-placard__label {
  font-family: var(--fur-font-sans);
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.25em;
  color: var(--fur-text-muted);
  opacity: 0.45;
  border-bottom: 1px solid var(--fur-border-light);
  padding-bottom: 6px;
}


/* === CONSOLIDATED INDEX6 STYLES === */
/* ==========================================================================
   ROOM COMPOSER COMPONENT STYLES
   WP-CONVERSION READY & RTL COMPLIANT
   ========================================================================== */

/* App Layout & Containers */
.tft-rc-body {
  margin: 0;
  padding: 0;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
  background-color: var(--fur-bg);
  color: var(--fur-text);
  font-family: var(--fur-font-sans);
}

.tft-rc-app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100%;
}

/* Loader Screen */
.tft-rc-loader {
  position: fixed;
  inset: 0;
  background-color: var(--fur-bg-secondary);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 100;
  transition: opacity 0.5s ease, visibility 0.5s ease;
}

.tft-rc-loader--hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.tft-rc-loader__blueprint {
  color: var(--fur-primary);
  margin-bottom: 20px;
  animation: tftBlueprintPulse 2s infinite ease-in-out;
}

.tft-rc-loader__text {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--fur-text);
  margin-bottom: 15px;
}

.tft-rc-loader__bar {
  width: 150px;
  height: 3px;
  background-color: var(--fur-border-light);
  border-radius: var(--fur-radius-full);
  overflow: hidden;
}

.tft-rc-loader__bar-fill {
  width: 30%;
  height: 100%;
  background-color: var(--fur-primary);
  border-radius: var(--fur-radius-full);
  animation: tftLoaderFill 1.5s infinite ease-in-out;
}

@keyframes tftBlueprintPulse {

  0%,
  100% {
    opacity: 0.7;
    transform: scale(0.98);
  }

  50% {
    opacity: 1;
    transform: scale(1.02);
  }
}

@keyframes tftLoaderFill {
  0% {
    transform: translateX(-100%);
  }

  100% {
    transform: translateX(100%);
  }
}

/* Header styling */
.tft-rc-header {
  height: 65px;
  background-color: var(--fur-bg-secondary);
  border-bottom: 1px solid var(--fur-border-light);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-inline: 20px;
  box-sizing: border-box;
  z-index: 10;
}

.tft-rc-header__left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.tft-rc-header__logo {
  font-family: var(--fur-font-serif);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--fur-text);
  text-decoration: none;
  line-height: 1;
}

.tft-rc-header__logo span {
  color: var(--fur-primary);
}

.tft-rc-header__back {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  text-decoration: none;
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--fur-text-muted);
  border: 1px solid var(--fur-border-light);
  padding: 5px 10px;
  border-radius: var(--fur-radius-full);
  transition: all var(--fur-transition-fast);
}

.tft-rc-header__back:hover {
  color: var(--fur-primary);
  border-color: var(--fur-primary);
}

.tft-rc-header__divider {
  width: 1px;
  height: 20px;
  background-color: var(--fur-border-light);
}

.tft-rc-header__title {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--fur-text);
}

.tft-rc-header__center {
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--fur-text-muted);
  max-width: 400px;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tft-rc-hbtn {
  background: none;
  border: 1px solid var(--fur-border-light);
  font-family: inherit;
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--fur-text);
  padding: 8px 16px;
  border-radius: var(--fur-radius-full);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all var(--fur-transition-fast);
}

.tft-rc-hbtn:hover {
  background-color: var(--fur-bg);
  border-color: var(--fur-text-muted);
}

.tft-rc-hbtn--primary {
  background-color: var(--fur-primary);
  border-color: var(--fur-primary);
  color: var(--fur-ref-white);
}

.tft-rc-hbtn--primary:hover {
  background-color: var(--fur-ref-charcoal);
  border-color: var(--fur-ref-charcoal);
}

/* Three Column Layout Grid */
.tft-rc-main {
  flex: 1;
  display: grid;
  grid-template-columns: 280px 1fr 340px;
  height: calc(100vh - 65px);
  overflow: hidden;
  box-sizing: border-box;
}

/* Panels */
.tft-rc-panel {
  background-color: var(--fur-bg-secondary);
  overflow-y: auto;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
}

.tft-rc-panel--left {
  border-inline-end: 1px solid var(--fur-border-light);
}

.tft-rc-panel--right {
  border-inline-start: 1px solid var(--fur-border-light);
}

.tft-rc-panel__section {
  padding: 20px;
  border-bottom: 1px solid var(--fur-border-light);
}

.tft-rc-panel__section--controls {
  margin-top: auto;
  background-color: rgba(0, 0, 0, 0.02);
}

.tft-rc-panel__heading {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--fur-text-muted);
  margin-top: 0;
  margin-bottom: 15px;
}

/* Left panel presets & custom input */
.tft-rc-presets {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.tft-rc-preset-btn {
  background-color: var(--fur-bg);
  border: 1px solid var(--fur-border-light);
  border-radius: var(--fur-radius-sm);
  padding: 12px 10px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  transition: all var(--fur-transition-fast);
}

.tft-rc-preset-btn svg {
  color: var(--fur-text-muted);
  transition: color var(--fur-transition-fast);
}

.tft-rc-preset-btn span {
  font-size: 0.65rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fur-text);
}

.tft-rc-preset-btn:hover {
  border-color: var(--fur-primary);
  background-color: var(--fur-bg-secondary);
}

.tft-rc-preset-btn:hover svg {
  color: var(--fur-primary);
}

.tft-rc-preset-btn--active {
  border-color: var(--fur-primary);
  background-color: rgba(136, 170, 102, 0.08);
