  position: relative;
  align-items: center;
}

.tft-rc-input {
  width: 100%;
  padding: 8px 30px 8px 12px;
  font-family: inherit;
  font-size: 0.82rem;
  border: 1px solid var(--fur-border-light);
  border-radius: var(--fur-radius-sm);
  background-color: var(--fur-bg);
  color: var(--fur-text);
  box-sizing: border-box;
}

.tft-rc-input-unit {
  position: absolute;
  right: 12px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--fur-text-muted);
}

.tft-rc-btn {
  background: none;
  font-family: inherit;
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 10px 18px;
  border-radius: var(--fur-radius-sm);
  cursor: pointer;
  transition: all var(--fur-transition-fast);
  text-align: center;
  border: 1px solid var(--fur-border-light);
}

.tft-rc-btn--full {
