}

.tft-rc-cart-item__left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tft-rc-cart-item__name {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--fur-text);
  letter-spacing: 0.02em;
}

.tft-rc-cart-item__desc {
  font-size: 0.62rem;
  color: var(--fur-text-muted);
}

.tft-rc-cart-item__right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.tft-rc-cart-item__price {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--fur-text);
}

.tft-rc-cart-item__delete {
  background: none;
  border: none;
