.tft-rc-cart__total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  font-size: 0.75rem;
}

.tft-rc-cart__total-row span {
  font-weight: 600;
  color: var(--fur-text-muted);
}

.tft-rc-cart__total-row strong {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--fur-text);
}

/* Right Panel: Catalog List */
.tft-rc-catalog {
