.tft-rc-features {
  padding-block: 10px !important;
}

.tft-rc-features__container {
  gap: 0 !important;
  padding-inline: 16px !important;
  align-items: center !important;
  max-width: 100% !important;
}

.tft-rc-feature-col {
  align-items: center !important;
  gap: 10px !important;
  padding-inline: 16px !important;
  border-inline-end: 1px solid var(--fur-border) !important;
}

.tft-rc-feature-col:last-child {
  border-inline-end: none !important;
}

.tft-rc-feature-col__icon-wrap {
  width: 28px !important;
  height: 28px !important;
  border-radius: 6px !important;
}

.tft-rc-feature-col__icon-wrap svg {
  width: 14px !important;
  height: 14px !important;
}

.tft-rc-feature-col__content {
  gap: 1px !important;
}

.tft-rc-feature-col__title {
  font-size: 0.64rem !important;
  letter-spacing: 0.07em !important;
}

.tft-rc-feature-col__desc {
  font-size: 0.67rem !important;
  line-height: 1.25 !important;
}

/* Compact canvas stats bar */
.tft-rc-stats {
  height: 32px !important;
  padding-inline: 12px !important;
  font-size: 0.64rem !important;
}

.tft-rc-stats__left {
  gap: 6px !important;
}

@media (max-width: 1024px) {
  .tft-rc-features__container {
    grid-template-columns: repeat(4, 1fr) !important;
    gap: 0 !important;
  }
}

@media (max-width: 600px) {
  .tft-rc-features__container {
    grid-template-columns: repeat(2, 1fr) !important;
  }

  .tft-rc-feature-col__desc {
    display: none !important;
  }
}

