.tft-ps-hero {
  position: relative;
  block-size: clamp(320px, 55vh, 600px);
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  margin-block-end: clamp(32px, 5vw, 64px);
}

.tft-ps-hero__bg-wrap {
  position: absolute;
  inset: 0;
}

.tft-ps-hero__bg-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 40%;
  transform: scale(1.04);
  transition: transform 8s ease;
}

.tft-ps-hero:hover .tft-ps-hero__bg-img {
  transform: scale(1.0);
}

.tft-ps-hero__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, hsla(0, 0%, 0%, .75) 0%, hsla(0, 0%, 0%, .2) 55%, transparent 100%);
}

.tft-ps-hero__inner {
  position: relative;
  z-index: 2;
  padding-inline: clamp(20px, 5vw, 72px);
  padding-block-end: clamp(28px, 4vw, 52px);
  color: #fff;
  max-width: 800px;
}

.tft-ps-breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-block-end: 14px;
  font-size: 0.75rem;
  font-family: var(--fur-font-sans);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  opacity: .85;
}

.tft-ps-breadcrumb__link {
  color: #fff;
  text-decoration: none;
}

.tft-ps-breadcrumb__link:hover {
  text-decoration: underline;
}

.tft-ps-breadcrumb__sep {
  opacity: .55;
}

.tft-ps-breadcrumb__current {
  opacity: .7;
}

.tft-ps-hero__tag {
  display: inline-block;
  background: hsla(255, 255%, 255%, .15);
  border: 1px solid hsla(255, 255%, 255%, .3);
  backdrop-filter: blur(6px);
  color: #fff;
  font-family: var(--fur-font-sans);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 5px 14px;
  border-radius: 999px;
  margin-block-end: 12px;
}

.tft-ps-hero__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.8rem, 4vw, 3.2rem);
  font-weight: 700;
  line-height: 1.15;
  margin-block-end: 10px;
  color: #fff;
}

.tft-ps-hero__desc {
  font-family: var(--fur-font-sans);
  font-size: clamp(0.88rem, 1.2vw, 1rem);
  opacity: .82;
  max-width: 540px;
