.tft-ps-gallery {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.tft-ps-gallery__stage {
  position: relative;
  background: var(--fur-bg-secondary);
  border-radius: var(--fur-radius-lg);
  overflow: hidden;
  aspect-ratio: 1 / 1;
}

.tft-ps-gallery__stage--hidden {
  display: none;
}

.tft-ps-gallery__main-wrap {
  width: 100%;
  height: 100%;
}

.tft-ps-gallery__main-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform .6s cubic-bezier(.16, 1, .3, 1);
}

.tft-ps-gallery__stage:hover .tft-ps-gallery__main-img {
  transform: scale(1.04);
}

.tft-ps-gallery__wish {
  position: absolute;
  inset-block-start: 14px;
  inset-inline-end: 14px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1.5px solid var(--fur-border);
  background: var(--fur-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 3;
  transition: background .2s, color .2s;
  color: var(--fur-text-muted);
}

.tft-ps-gallery__wish:hover {
  background: var(--fur-primary);
  color: #fff;
  border-color: var(--fur-primary);
}

.tft-ps-gallery__counter {
  position: absolute;
  inset-block-end: 14px;
  inset-inline-start: 14px;
  background: hsla(0, 0%, 0%, .55);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
  font-family: var(--fur-font-sans);
  z-index: 3;
}

/* View toggle pills */
.tft-ps-view-toggle {
  display: flex;
  gap: 0;
  border: 1.5px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  overflow: hidden;
  margin-block-start: 14px;
}

.tft-ps-view-toggle__btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 10px 16px;
  font-family: var(--fur-font-sans);
  font-size: 0.78rem;
  font-weight: 600;
  background: var(--fur-surface);
  color: var(--fur-text-muted);
  border: none;
  cursor: pointer;
  transition: background .2s, color .2s;
}

.tft-ps-view-toggle__btn+.tft-ps-view-toggle__btn {
  border-inline-start: 1.5px solid var(--fur-border);
}

.tft-ps-view-toggle__btn--active {
  background: var(--fur-primary);
  color: #fff;
}

