.tft-ps-details {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.tft-ps-det__category {
  display: inline-block;
  font-family: var(--fur-font-sans);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--fur-primary);
  margin-block-end: 8px;
}

.tft-ps-det__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.6rem, 3vw, 2.6rem);
  font-weight: 700;
  line-height: 1.2;
  margin-block-end: 12px;
  color: var(--fur-text);
}

.tft-ps-det__rating {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-block-end: 18px;
}

.tft-ps-det__stars {
  color: hsl(40, 90%, 50%);
  font-size: 1rem;
  letter-spacing: 1px;
}

.tft-ps-det__review-count {
  font-size: 0.8rem;
  color: var(--fur-text-muted);
  font-family: var(--fur-font-sans);
}

.tft-ps-det__price-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-block-end: 12px;
}

.tft-ps-det__price {
  font-family: var(--fur-font-serif);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 700;
  color: var(--fur-text);
}

.tft-ps-det__price-orig {
  font-size: 1rem;
  color: var(--fur-text-muted);
  text-decoration: line-through;
  font-family: var(--fur-font-sans);
}

.tft-ps-det__sale-badge {
  background: hsl(4, 86%, 58%);
  color: #fff;
  font-size: 0.65rem;
  font-weight: 800;
  padding: 3px 9px;
  border-radius: 999px;
  font-family: var(--fur-font-sans);
  letter-spacing: 0.05em;
}

.tft-ps-det__desc {
  font-family: var(--fur-font-sans);
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--fur-text-muted);
  margin-block: 14px 22px;
}

.tft-ps-det__group {
  margin-block-end: 22px;
}

.tft-ps-det__label {
  display: block;
  font-family: var(--fur-font-sans);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fur-text-muted);
  margin-block-end: 10px;
}

.tft-ps-det__swatches {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-block-end: 8px;
}

.tft-ps-det__swatch {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--sw-bg, hsl(30, 28%, 62%));
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform .18s, border-color .18s;
  outline-offset: 3px;
}

.tft-ps-det__swatch:hover {
  transform: scale(1.15);
}

.tft-ps-det__swatch--active {
  border-color: var(--fur-primary);
  outline: 2px solid var(--fur-primary);
}

.tft-ps-det__swatch-name {
  font-size: 0.78rem;
  color: var(--fur-text-muted);
  font-family: var(--fur-font-sans);
}

.tft-ps-det__specs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border: 1.5px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  overflow: hidden;
  margin-block-end: 22px;
}

.tft-ps-det__spec {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 14px;
  background: var(--fur-bg-secondary);
}

.tft-ps-det__spec+.tft-ps-det__spec {
  border-inline-start: 1.5px solid var(--fur-border);
}

.tft-ps-det__spec span {
  font-size: 0.68rem;
  font-family: var(--fur-font-sans);
  color: var(--fur-text-muted);
  text-transform: uppercase;
  letter-spacing: .06em;
}

.tft-ps-det__spec strong {
  font-size: 0.9rem;
  font-family: var(--fur-font-sans);
  font-weight: 700;
  color: var(--fur-text);
}

.tft-ps-det__qty-row {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-block-end: 22px;
}

.tft-ps-det__stepper {
  display: flex;
  align-items: center;
  border: 1.5px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  overflow: hidden;
}

.tft-ps-det__step-btn {
  width: 40px;
  height: 42px;
  border: none;
  background: var(--fur-bg-secondary);
  color: var(--fur-text);
  font-size: 1.1rem;
  cursor: pointer;
  font-family: var(--fur-font-sans);
  transition: background .2s;
}

.tft-ps-det__step-btn:hover {
  background: var(--fur-border);
}

.tft-ps-det__qty-input {
  width: 48px;
  height: 42px;
  border: none;
  border-inline: 1.5px solid var(--fur-border);
  text-align: center;
  font-family: var(--fur-font-sans);
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--fur-text);
  background: var(--fur-surface);
  -moz-appearance: textfield;
}

.tft-ps-det__qty-input::-webkit-inner-spin-button,
.tft-ps-det__qty-input::-webkit-outer-spin-button {
  appearance: none;
}

.tft-ps-det__actions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-block-end: 22px;
}

.tft-ps-det__add-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 16px 32px;
  background: var(--fur-primary);
  color: #fff;
  border: none;
  border-radius: var(--fur-radius-md);
  font-family: var(--fur-font-sans);
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: filter .2s, transform .18s;
}

.tft-ps-det__add-btn:hover {
  filter: brightness(1.12);
  transform: translateY(-1px);
}

.tft-ps-det__room-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 14px 32px;
  border: 1.5px solid var(--fur-primary);
  border-radius: var(--fur-radius-md);
  color: var(--fur-primary);
  font-family: var(--fur-font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  text-decoration: none;
  transition: background .2s, color .2s;
}

.tft-ps-det__room-btn:hover {
  background: var(--fur-primary);
  color: #fff;
}

.tft-ps-det__delivery {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  background: var(--fur-bg-secondary);
  border-radius: var(--fur-radius-md);
  border: 1px solid var(--fur-border);
  margin-block-end: 24px;
}

.tft-ps-det__delivery-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  color: var(--fur-text-muted);
}

.tft-ps-det__delivery-item svg {
  flex-shrink: 0;
  color: var(--fur-primary);
}

