.tft-ps-trust {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-block: 1.5px solid var(--fur-border);
  margin-block-end: clamp(48px, 7vw, 100px);
}

@media (max-width: 720px) {
  .tft-ps-trust {
    grid-template-columns: repeat(2, 1fr);
  }
}

.tft-ps-trust__item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: clamp(20px, 3vw, 32px) clamp(20px, 4vw, 48px);
  border-inline-end: 1.5px solid var(--fur-border);
}

.tft-ps-trust__item:last-child {
  border-inline-end: none;
}

.tft-ps-trust__item svg {
  color: var(--fur-primary);
  flex-shrink: 0;
}

.tft-ps-trust__item div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.tft-ps-trust__item strong {
  font-family: var(--fur-font-sans);
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--fur-text);
}

.tft-ps-trust__item span {
  font-family: var(--fur-font-sans);
  font-size: 0.73rem;
  color: var(--fur-text-muted);
}

