}

/* Ensure all page-heros are full width, aligned, and never boxed */
body.fur-body:not(.tft-fnd-body):not(.tft-rc-body) .tft-shop-catalog>.tft-post-hero,
body.tft-page-journal:not(.tft-fnd-body):not(.tft-rc-body) .tft-shop-catalog>.tft-post-hero,
body.fur-body:not(.tft-fnd-body):not(.tft-rc-body) .tft-post-hero,
body.tft-page-journal:not(.tft-fnd-body):not(.tft-rc-body) .tft-post-hero,
.tft-post-hero {
  max-width: none !important;
  width: 100% !important;
  margin-inline: 0 !important;
  margin-block-start: 0 !important;
  padding-inline: 0 !important;
  border-radius: 0 !important;
  box-sizing: border-box !important;
}

/* Exempt the top header container from any boxing restrictions on inner pages */
body.fur-body:not(.tft-fnd-body):not(.tft-rc-body) .tft-shop-catalog,
body.fur-body:not(.tft-fnd-body):not(.tft-rc-body) .tft-ps-section {
