  width: 100% !important;
  margin-inline: 0 !important;
  margin-block-start: 0 !important;
  padding-inline: 0 !important;
  padding-block-start: 0 !important;
  /* GLUE TO HEADER */
}

/* Re-apply boxing layout constraint strictly to content children following the hero banner */
body.fur-body:not(.tft-fnd-body):not(.tft-rc-body) .tft-shop-catalog>*:not(.tft-post-hero),
body.fur-body:not(.tft-fnd-body):not(.tft-rc-body) .tft-ps-section>*:not(.tft-post-hero) {
