  margin-inline: auto !important;
  width: 100% !important;
  padding-inline: clamp(16px, 4vw, 80px) !important;
}


/* ==========================================================================
   TFT MATERIAL LAB MODULE STYLING
   ========================================================================== */

/* Main Page Container and Layout */
.tft-mat-lab {
  display: flex;
  flex-direction: column;
  background-color: var(--fur-bg);
  min-height: 100vh;
}

.tft-mat-lab__intro {
  margin-block-start: clamp(32px, 5vw, 64px);
  margin-block-end: clamp(24px, 4vw, 48px);
  text-align: center;
  max-width: 800px;
  margin-inline: auto;
}

.tft-mat-lab__subtitle {
  font-family: var(--fur-font-sans);
  font-size: clamp(0.75rem, 0.9vw, 0.85rem);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--fur-primary);
  margin-block-end: 12px;
  display: block;
}

.tft-mat-lab__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(2rem, 3.5vw, 3.2rem);
  font-weight: 700;
  color: var(--fur-text);
  line-height: 1.2;
  margin-block-end: 16px;
}

.tft-mat-lab__description {
  font-family: var(--fur-font-sans);
  font-size: var(--fur-fs-body);
  color: var(--fur-text-muted);
  line-height: 1.6;
}

/* Category Filters Bar */
.tft-mat-lab__filter-wrapper {
  margin-block-end: clamp(32px, 5vw, 64px);
  position: sticky;
  top: 80px;
  /* Below horizontal sticky header */
  z-index: 90;
  background-color: color-mix(in srgb, var(--fur-bg) 95%, transparent);
  backdrop-filter: blur(10px);
  padding-block: 16px;
  border-block: 1px solid var(--fur-border);
}

.tft-mat-lab__filters {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  max-width: 1400px;
  margin-inline: auto;
}

.tft-mat-filter-btn {
  background: transparent;
  border: 1px solid var(--fur-border);
  color: var(--fur-text);
  font-family: var(--fur-font-sans);
  font-size: clamp(0.75rem, 0.9vw, 0.85rem);
  font-weight: 500;
  padding-inline: 20px;
  padding-block: 10px;
  border-radius: var(--fur-radius-full);
  cursor: pointer;
  transition: all var(--fur-transition-fast);
}

.tft-mat-filter-btn:hover {
  background-color: var(--fur-bg-secondary);
  border-color: var(--fur-text-muted);
}

.tft-mat-filter-btn--active {
  background-color: var(--fur-primary) !important;
  color: var(--fur-ref-white) !important;
  border-color: var(--fur-primary) !important;
}

/* Materials Swatch Grid */
.tft-swatch-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 32px;
  margin-block-end: clamp(48px, 8vw, 96px);
}

.tft-swatch-card {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--fur-transition-normal), box-shadow var(--fur-transition-normal), border-color var(--fur-transition-normal);
  position: relative;
}

.tft-swatch-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 12px 32px var(--fur-shadow-lg);
  border-color: var(--fur-primary);
}

.tft-swatch-card--selected {
  border-color: var(--fur-primary);
  outline: 2px solid var(--fur-primary);
  outline-offset: -2px;
}

.tft-swatch-card__media {
  position: relative;
  width: 100%;
  padding-top: 100%;
  /* 1:1 Aspect Ratio */
  overflow: hidden;
  background-color: var(--fur-bg-secondary);
}

.tft-swatch-card__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 6s cubic-bezier(0.16, 1, 0.3, 1);
}

.tft-swatch-card:hover .tft-swatch-card__img {
  transform: scale(1.08);
}

.tft-swatch-card__badge {
  position: absolute;
  inset-block-start: 16px;
  inset-inline-start: 16px;
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  font-family: var(--fur-font-sans);
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding-inline: 10px;
  padding-block: 5px;
  border-radius: var(--fur-radius-sm);
  z-index: 2;
}

.tft-swatch-card__selected-icon {
  position: absolute;
  inset-block-start: 16px;
  inset-inline-end: 16px;
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  width: 28px;
  height: 28px;
  border-radius: var(--fur-radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  opacity: 0;
  transform: scale(0.6);
  transition: all var(--fur-transition-fast);
}

.tft-swatch-card--selected .tft-swatch-card__selected-icon {
  opacity: 1;
  transform: scale(1);
}

.tft-swatch-card__info {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.tft-swatch-card__name {
  font-family: var(--fur-font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--fur-text);
  margin-block-end: 6px;
}

.tft-swatch-card__meta {
  font-family: var(--fur-font-sans);
  font-size: 0.78rem;
  color: var(--fur-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-block-end: 12px;
}

.tft-swatch-card__desc {
  font-family: var(--fur-font-sans);
  font-size: 0.85rem;
  color: var(--fur-text-muted);
  line-height: 1.5;
  margin-block-end: 20px;
  flex-grow: 1;
}

.tft-swatch-card__action {
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-primary);
  color: var(--fur-primary);
  font-family: var(--fur-font-sans);
  font-size: 0.8rem;
  font-weight: 600;
  padding-block: 10px;
  text-align: center;
  border-radius: var(--fur-radius-sm);
  cursor: pointer;
  transition: all var(--fur-transition-fast);
  width: 100%;
}

.tft-swatch-card__action:hover {
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
}

.tft-swatch-card--selected .tft-swatch-card__action {
  background-color: var(--fur-bg-secondary);
  border-color: var(--fur-border-light);
  color: var(--fur-text-muted);
}

.tft-swatch-card--selected .tft-swatch-card__action:hover {
  background-color: var(--fur-primary);
  border-color: var(--fur-primary);
  color: var(--fur-ref-white);
}

/* Float Tray Sticky Widget (Trigger) */
.tft-tray-widget {
  position: fixed;
  inset-block-end: 32px;
  inset-inline-end: 32px;
  z-index: 110;
  display: flex;
  align-items: center;
  gap: 12px;
}

.tft-tray-trigger {
  background-color: var(--fur-primary);
  color: var(--fur-ref-white);
  border: none;
  border-radius: var(--fur-radius-full);
  padding-inline: 24px;
  padding-block: 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--fur-font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  box-shadow: 0 12px 40px var(--fur-shadow-lg);
  cursor: pointer;
  transition: transform var(--fur-transition-fast), background-color var(--fur-transition-fast);
}

.tft-tray-trigger:hover {
  transform: translateY(-4px);
  background-color: var(--fur-primary-hover);
}

.tft-tray-trigger__badge {
  background-color: var(--fur-ref-white);
  color: var(--fur-primary);
  width: 22px;
  height: 22px;
  border-radius: var(--fur-radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
}

/* Tray Drawer Sidebar */
.tft-tray-drawer {
  position: fixed;
  inset-block-start: 0;
  inset-inline-end: 0;
  width: 420px;
  max-width: 100vw;
  height: 100vh;
  background-color: var(--fur-surface);
  box-shadow: -10px 0 50px var(--fur-shadow-lg);
  z-index: 1200;
  transform: translateX(100%);
  transition: transform var(--fur-transition-normal);
  display: flex;
  flex-direction: column;
}

.tft-tray-drawer--open {
  transform: translateX(0);
}

.tft-tray-drawer__header {
  padding: 24px;
  border-bottom: 1px solid var(--fur-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tft-tray-drawer__title {
  font-family: var(--fur-font-serif);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--fur-text);
}

.tft-tray-drawer__close {
  background: none;
  border: none;
  font-size: 1.8rem;
  cursor: pointer;
  color: var(--fur-text-muted);
  transition: color var(--fur-transition-fast);
  display: flex;
  align-items: center;
  justify-content: center;
}

.tft-tray-drawer__close:hover {
