  overflow-x: auto;
  scrollbar-width: none;
  padding-block: 8px;
  scroll-behavior: smooth;
  cursor: grab;
  user-select: none;
}

.tft-eds-carousel__track::-webkit-scrollbar {
  display: none;
}

.tft-eds-carousel__track--dragging {
  cursor: grabbing;
  scroll-behavior: auto;
}

/* Carousel Product Cards */
.tft-eds-product-card {
  flex: 0 0 220px;
  display: flex;
  flex-direction: column;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: var(--fur-radius-md);
  padding: 12px;
  box-shadow: 0 4px 12px var(--fur-shadow);
  transition: all var(--fur-transition-normal);
}

.tft-eds-product-card:hover {
  transform: translateY(-4px);
  border-color: var(--fur-primary);
  box-shadow: 0 8px 24px var(--fur-shadow-lg);
}

.tft-eds-product-card__img-wrapper {
  position: relative;
  overflow: hidden;
  border-radius: var(--fur-radius-sm);
  background-color: var(--fur-bg-secondary);
  aspect-ratio: 1;
  margin-block-end: 12px;
}

.tft-eds-product-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--fur-transition-normal);
}

.tft-eds-product-card:hover .tft-eds-product-card__img {
  transform: scale(1.05);
}

.tft-eds-product-card__add {
  position: absolute;
  inset-inline-end: 8px;
  inset-block-end: 8px;
  width: 32px;
  height: 32px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-surface);
  color: var(--fur-text);
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: 700;
  font-size: 16px;
  box-shadow: 0 2px 8px var(--fur-shadow-lg);
  transition: all var(--fur-transition-fast);
}

.tft-eds-product-card__add:hover {
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  transform: scale(1.1);
}

.tft-eds-product-card__body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tft-eds-product-card__title {
  font-family: var(--fur-font-sans);
  font-size: 13px;
  font-weight: 600;
  color: var(--fur-text);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tft-eds-product-card__price {
  font-family: var(--fur-font-sans);
  font-size: 13px;
  font-weight: 700;
  color: var(--fur-primary);
}

.tft-eds-product-card__swatches {
  display: flex;
  gap: 6px;
  margin-block-start: 4px;
}

.tft-eds-product-card__swatch {
  width: 10px;
  height: 10px;
  border-radius: var(--fur-radius-full);
  border: 1px solid var(--fur-border);
  cursor: pointer;
}

.tft-eds-product-card__swatch--active {
  box-shadow: 0 0 0 1px var(--fur-surface), 0 0 0 2px var(--fur-primary);
}

/* Materials Promo Section */
.tft-eds-promo {
  padding-block: clamp(60px, 10vw, 120px);
  padding-inline: clamp(16px, 4vw, 48px);
  background-color: var(--fur-bg-secondary);
  text-align: center;
  border-block-end: 1px solid var(--fur-border);
  position: relative;
  overflow: hidden;
}

.tft-eds-promo::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url('../img/fur_material_sample_tray.png');
  background-size: cover;
  background-position: center;
  opacity: 0.04;
  pointer-events: none;
}

.tft-eds-promo__container {
  max-width: 800px;
  margin-inline: auto;
  position: relative;
  z-index: 2;
}

.tft-eds-promo__content {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.tft-eds-promo__eyebrow {
  font-family: var(--fur-font-sans);
  font-size: var(--fur-fs-small);
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--fur-primary);
  margin-block-end: 16px;
  text-transform: uppercase;
}

.tft-eds-promo__title {
  font-family: var(--fur-font-serif);
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 400;
  line-height: 1.25;
  color: var(--fur-text);
  margin-block-end: 20px;
}

.tft-eds-promo__desc {
  font-family: var(--fur-font-sans);
  font-size: clamp(14px, 1.2vw, 17px);
  line-height: 1.6;
  color: var(--fur-text-muted);
  margin-block-end: 36px;
}

.tft-eds-promo__btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding-block: 16px;
  padding-inline: 32px;
  border-radius: var(--fur-radius-full);
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  font-family: var(--fur-font-sans);
  font-size: var(--fur-fs-small);
  font-weight: 600;
  letter-spacing: 0.05em;
  transition: all var(--fur-transition-normal);
  border: 1px solid var(--fur-primary);
}

.tft-eds-promo__btn:hover {
  background-color: var(--fur-primary-hover);
  border-color: var(--fur-primary-hover);
  transform: translateY(-2px);
}

/* IntersectionObserver Scroll Reveals */
.tft-eds-reveal {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.tft-eds-reveal--visible {
  opacity: 1;
  transform: translateY(0);
}

