}

@keyframes tftHotspotPulse {
  0% {
    transform: scale(1);
    opacity: 0.45;
  }

  100% {
    transform: scale(2.2);
    opacity: 0;
  }
}

.tft-sth-popup {
  position: absolute;
  bottom: 40px;
  inset-inline-start: 50%;
  transform: translateX(-50%) translateY(10px);
  width: 280px;
