  content: "";
  position: absolute;
  top: 100%;
  inset-inline-start: 50%;
  transform: translateX(-50%);
  border-width: 8px;
  border-style: solid;
  border-color: var(--fur-surface) transparent transparent transparent;
}

.tft-sth-popup::before {
  content: "";
  position: absolute;
  top: 100%;
  inset-inline-start: 50%;
  transform: translateX(-50%);
  border-width: 9px;
  border-style: solid;
  border-color: var(--fur-border) transparent transparent transparent;
  z-index: -1;
}

.tft-sth-popup--active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

