  .tft-fms-card--standard {
    grid-column: span 1;
    grid-row: span 1;
  }

  .tft-fms-card--landscape .fur-product-card__info {
    position: relative;
    background-color: var(--fur-card-bg, var(--fur-surface));
    color: var(--fur-text);
    padding: 16px;
  }

  .tft-fms-card--landscape .fur-product-card__title {
    color: var(--fur-text) !important;
  }

  .tft-fms-card--landscape .fur-product-card__price {
    color: var(--fur-text-muted) !important;
  }
}

@media (max-width: 991px) {
  .tft-fms-container {
    grid-template-columns: 1fr;
  }

  .tft-fms-sidebar {
    position: relative;
    top: 0;
    height: auto;
    border-inline-end: none;
    padding-inline-end: 0;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 24px;
  }

  .tft-fms-sidebar__section {
    flex: 1 1 200px;
  }
}

@media (max-width: 576px) {
  .tft-fms-sidebar {
    flex-direction: column;
  }

  .tft-fms-catalog__grid {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================================
   TFT - PRESET TRENDING NOW PRODUCT HOVER OVERRIDES
   ========================================================================== */
body.fur-layout-classic .fur-trending__product-item {
  position: relative !important;
  border-inline-start: none !important;
  /* Remove static left border override */
  padding-inline-start: 12px !important;
