  --tft-translate-x: 64px;
  --tft-thumb-size: 48px;
  --tft-thumb-left: 48px;
}

@media (max-width: 480px) {
  body.fur-layout-classic .fur-trending__product-item {
    --tft-translate-x: 52px;
