    --tft-thumb-left: 42px;
  }
}

/* Left animated border line that grows vertically from center */
body.fur-layout-classic .fur-trending__product-item::before {
  content: "" !important;
  position: absolute !important;
  inset-block: 0 !important;
  inset-inline-start: 0 !important;
  width: 3px !important;
  background-color: var(--fur-primary) !important;
  transform: scaleY(0) !important;
  transform-origin: center !important;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1) !important;
  z-index: 2 !important;
}

body.fur-layout-classic .fur-trending__product-item:hover::before {
  transform: scaleY(1) !important;
}

/* Soft card shadow & glassmorphic bg on hover */
body.fur-layout-classic .fur-trending__product-item:hover {
  background-color: var(--fur-bg-secondary) !important;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.05), 0 8px 24px -8px var(--fur-shadow-lg) !important;
  transform: translateX(4px) !important;
}

/* Animated product thumbnail image preview container */
body.fur-layout-classic .fur-trending__product-item::after {
  content: "" !important;
  position: absolute !important;
  inset-inline-start: var(--tft-thumb-left) !important;
  inset-block-start: calc(50% - (var(--tft-thumb-size) / 2)) !important;
  width: var(--tft-thumb-size) !important;
  height: var(--tft-thumb-size) !important;
  border-radius: var(--fur-radius-sm) !important;
  background-size: cover !important;
  background-position: center !important;
  opacity: 0 !important;
  transform: translateX(-12px) scale(0.85) !important;
  transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1), transform 0.4s cubic-bezier(0.16, 1, 0.3, 1) !important;
  pointer-events: none !important;
  border: 1px solid var(--fur-border) !important;
  box-shadow: 0 4px 12px var(--fur-shadow) !important;
  z-index: 1 !important;
}

body.fur-layout-classic .fur-trending__product-item:hover::after {
  opacity: 1 !important;
  transform: translateX(0) scale(1) !important;
}

/* Dynamic background images based on product items in the list */
body.fur-layout-classic .fur-trending__product-list .fur-trending__product-item:nth-child(1)::after {
  background-image: url('../img/fur_sofa_boucle.png') !important;
