        color-mix(in srgb, var(--fur-ref-beige-50) 90%, transparent) 85%,
        color-mix(in srgb, var(--fur-ref-beige-50) 40%, transparent) 100%) !important;
  }

  [dir="rtl"] body[data-theme="dark"].tft-page-journal .tft-sound--v2 .tft-sound__hero-overlay,
  [dir="rtl"] body[data-theme="dark"] .tft-sound--v2 .tft-sound__hero-overlay {
    background: linear-gradient(to left,
        var(--fur-ref-forest-900) 0%,
        var(--fur-ref-forest-900) 70%,
