  /* Override default :hover rule when data-open is not true yet */
  .tft-mega--has-dropdown:hover:not([data-open="true"]) .tft-mega__panel {
    opacity: 0 !important;
    visibility: hidden !important;
    pointer-events: none !important;
    transform: translateY(-8px) !important;
  }

  .tft-mega--has-dropdown:hover:not([data-open="true"]) .tft-mega__chevron {
    transform: rotate(0deg) !important;
    color: var(--fur-text-muted) !important;
  }

  /* 2. Create an invisible bridge (pseudo-element) above the mega panel.
     This fills the physical gap between the navigation link and the panel,
     ensuring that the mouse remains "inside" the hover zone while moving down. */
  .tft-mega__panel::before {
    content: '';
    position: absolute;
    top: -45px;
    /* Extend upwards to bridge the gap to the navigation item */
    left: 0;
    right: 0;
    height: 45px;
    /* Match the gap distance */
    background: transparent;
    pointer-events: auto;
    /* Allow mouse interaction */
    z-index: 10;
  }
}

