/* =========================================================================
   7. About Page â€” Slow Craft Timeline (Premium 2Ã—2 Card Grid)
   ========================================================================= */

.tft-slow-craft__container {
  max-width: 1400px;
  width: 100%;
  margin-inline: auto;
  padding-inline: 0;
  box-sizing: border-box;
}

/* 2-column card grid with CSS counter decorative numbers */
.tft-slow-craft__timeline {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: clamp(12px, 1.6vw, 20px);
  counter-reset: tft-craft-step;
}

.tft-slow-craft__line {
  display: none;
}

/* Each step â€” premium card */
.tft-slow-craft__step {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background-color: var(--fur-surface);
  border: 1px solid var(--fur-border);
  border-radius: 16px;
  padding: clamp(24px, 2.5vw, 36px);
  position: relative;
  overflow: hidden;
  counter-increment: tft-craft-step;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s ease;
}

.tft-slow-craft__step:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 40px color-mix(in srgb, var(--fur-text-primary) 7%, transparent);
}

/* Large faded step number â€” decorative, bottom-right */
.tft-slow-craft__step::after {
  content: "0" counter(tft-craft-step);
  position: absolute;
  inset-block-end: -12px;
  inset-inline-end: 16px;
  font-family: var(--fur-font-serif);
  font-size: clamp(5rem, 8vw, 7rem);
  font-weight: 800;
  color: var(--fur-border);
  line-height: 1;
  letter-spacing: -0.04em;
  pointer-events: none;
  user-select: none;
}

.tft-slow-craft__node {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background-color: var(--fur-bg);
  border: 1.5px solid var(--fur-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--fur-text-primary);
  transition: border-color 0.3s ease, background-color 0.3s ease, color 0.3s ease;
}

.tft-slow-craft__step:hover .tft-slow-craft__node {
  border-color: var(--fur-accent);
  background-color: var(--fur-accent);
  color: var(--fur-bg);
}

.tft-slow-craft__content {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.tft-slow-craft__phase {
  display: block;
  font-family: var(--fur-font-sans);
