.tft-fnd-island {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(255, 255, 255, 0.45);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--fur-border);
  padding: 6px;
  border-radius: var(--fur-radius-full);
  box-shadow: 0 10px 40px var(--fur-shadow-lg);
  box-sizing: border-box;
  overflow-x: auto;
  max-width: 100%;
}

body[data-theme="dark"] .tft-fnd-island {
  background: rgba(20, 25, 20, 0.6);
}

.tft-fnd-island__btn {
  background: transparent;
  border: none;
  font-family: var(--fur-font-sans);
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--fur-text);
  padding: 10px clamp(12px, 2vw, 20px);
  border-radius: var(--fur-radius-full);
  cursor: pointer;
  transition: background-color var(--fur-transition-fast) ease, color var(--fur-transition-fast) ease, transform var(--fur-transition-fast) ease;
  white-space: nowrap;
}

.tft-fnd-island__btn:hover {
  transform: scale(1.03);
}

.tft-fnd-island__btn--active {
