/* Specs table */
.tft-fnd-drawer__specs {
  border-top: 1px solid var(--fur-border);
  padding-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tft-fnd-drawer__spec {
  display: flex;
  justify-content: space-between;
  font-size: 0.78rem;
}

.tft-fnd-drawer__spec-label {
  color: var(--fur-text-muted);
}

.tft-fnd-drawer__spec-val {
  font-weight: 600;
  color: var(--fur-text);
}

.tft-fnd-drawer__btn {
  background-color: var(--fur-primary);
  border: 1px solid var(--fur-primary);
  color: var(--fur-button-text);
  padding: 18px;
  font-family: var(--fur-font-sans);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: var(--fur-radius-sm);
  cursor: pointer;
  transition: background-color var(--fur-transition-fast) ease, border-color var(--fur-transition-fast) ease;
  margin-top: auto;
}

.tft-fnd-drawer__btn:hover {
  background-color: var(--fur-primary-hover);
  border-color: var(--fur-primary-hover);
}

/* Loading Overlay Screen */
.tft-fnd-loader {
  position: fixed;
  inset: 0;
  background-color: var(--fur-bg);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 16px;
  z-index: 100;
  transition: opacity 0.5s ease;
}

.tft-fnd-loader__spinner {
  width: 40px;
  height: 40px;
  border: 2px solid var(--fur-border);
  border-top-color: var(--fur-primary);
  border-radius: var(--fur-radius-full);
  animation: tft-spin 0.8s linear infinite;
}

.tft-fnd-loader__text {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--fur-text-muted);
}

@keyframes tft-spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

/* Action Feedback Toast */
.tft-fnd-toast {
  position: fixed;
  top: 30px;
  left: 50%;
  transform: translateX(-50%) translateY(-20px);
  background-color: var(--fur-primary);
  color: var(--fur-button-text);
  padding: 12px 24px;
  border-radius: var(--fur-radius-full);
  font-size: 0.78rem;
  font-weight: 600;
  box-shadow: 0 10px 30px var(--fur-shadow-lg);
  z-index: 50;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

.tft-fnd-toast--visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* Scrollbar styling for drawer */
.tft-fnd-drawer__body::-webkit-scrollbar {
  width: 4px;
}

.tft-fnd-drawer__body::-webkit-scrollbar-track {
  background: transparent;
}

.tft-fnd-drawer__body::-webkit-scrollbar-thumb {
  background: var(--fur-border-light);
  border-radius: var(--fur-radius-full);
}

/* 3D Typography Parallax Watermark Backdrop */
.tft-fnd-scene__backdrop {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate3d(-50%, -50%, -600px);
  transform-style: preserve-3d;
  text-align: center;
  pointer-events: none;
  white-space: nowrap;
  user-select: none;
  opacity: 0.06;
  transition: opacity var(--fur-transition-normal) ease;
}

body[data-theme="dark"] .tft-fnd-scene__backdrop {
  opacity: 0.035;
}

.tft-fnd-scene__backdrop-main {
  font-family: var(--fur-font-serif);
  font-size: clamp(8rem, 24vw, 22rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.15em;
  color: var(--fur-text);
  text-transform: uppercase;
}

.tft-fnd-scene__backdrop-sub {
  font-family: var(--fur-font-sans);
  font-size: clamp(0.7rem, 2vw, 1.1rem);
  font-weight: 600;
  letter-spacing: 0.35em;
  color: var(--fur-text);
  margin-top: 20px;
  text-transform: uppercase;
}

/* Spatial Section Placards */
.tft-fnd-placard {
  position: absolute;
  left: 0;
  top: 0;
  transform-style: preserve-3d;
  pointer-events: none;
  white-space: nowrap;
  user-select: none;
}

.tft-fnd-placard__label {
  font-family: var(--fur-font-sans);
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.25em;
  color: var(--fur-text-muted);
  opacity: 0.45;
  border-bottom: 1px solid var(--fur-border-light);
  padding-bottom: 6px;
}


