/* =============================================================
   UTILITY: .sr-only — Screen-reader only visually hidden class
   Required for W3C heading-in-section compliance fixes.
   ============================================================= */
.sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}